// One learner goal (canDo) and 4+ specific sub-goals per B1 lesson, shared by all three sheets
// (docs/LESSON_QUALITY_CONTRACT.md A1–A3, owner 2026-10-12). Lessons 1–50 come from their reviewed Avasta sheets,
// 51–75 were rewritten from the generic course defaults. Block goal ids (g_vocab, g_read, g_notice, g_use) stay.
export const B1_LESSON_GOALS = {
  "a2b1-001": {"canDo": "Ma räägin ilma abita endast, loen lühikest teksti, kirjutan õpetajale lühikese sõnumi ja saan teada, mida pean harjutama.", "goals": {"g_read": "Õpilane valib igapäevases olukorras sobiva lause ja leiab Eesti keelte tekstist arvud ja faktid (emakeeled, võõrkeeled, protsendid).", "g_notice": "Õpilane näitab, kuidas ta kasutab viit A2 vormi: kohakäänded, lihtminevik ja eitus, osastav, ma- ja da-vorm ning viisakas palve.", "g_use": "Õpilane räägib ilma abita 30–60 sekundit endast ja kirjutab õpetajale 30–50-sõnalise sõnumi; õpetaja märgib lähtepunkti."}, "tags": {"001_d_cold": "g_use"}},
  "a2b1-002": {"canDo": "Ma kirjutan oma õpetajale 30–60-sõnalise sõnumi: miks ma hiljaks jäin, millal ma kohale jõudsin ja mida ma järgmisel korral teisiti teen.", "goals": {"g_vocab": "Õpilane kasutab hilinemise ja ühistranspordi sõnu: hiljaks jääma, maha jääma, magama jääma, sõiduplaan, peatus, ummik, õnneks, kahjuks.", "g_read": "Õpilane leiab tekstist „Kuidas Eestis tööle ja kooli jõutakse?” fakte Eesti ajakasutuse ja Tallinna ühistranspordi kohta ning võrdleb neid oma eluga.", "g_notice": "Õpilane moodustab lihtmineviku jaatava ja eitava vormi (jäin, buss ei tulnud) ja paneb ajasõna järel tegusõna teisele kohale.", "g_use": "Õpilane räägib oma hilinemisest ja kirjutab oma päris õpetajale sõnumi: mis juhtus, millal ta kohale jõudis ja mida teeb teisiti."}, "tags": {"002_d_hook": "g_vocab", "002_t_exit": "g_vocab", "002_d_read": "g_read", "002_d_think": "g_read", "002_p_story": "g_notice", "002_p_sent": "g_notice", "002_t_msg": "g_use", "002_t_home": "g_use"}},
  "a2b1-003": {"canDo": "Ma räägin oma liikumisharjumustest ja annan sõbrale kaks nõu, kuidas rohkem liikuda.", "goals": {"g_vocab": "Õpilane kasutab liikumise ja harjumuste sõnu: liikuma, harjumus, soovitus, tervislik, trepp, regulaarselt, vähemalt, piisavalt, istuma.", "g_read": "Õpilane leiab Tervise Arengu Instituudi andmetest, kui palju Eesti inimesed liiguvad ja mida soovitused ütlevad, ning võrdleb ennast nendega.", "g_notice": "Õpilane kasutab osastavat sihitist (joon kohvi, ei söö kooki) ja valib ma- või da-vormi (pean liikuma, tahan joosta).", "g_use": "Õpilane küsib sõbra päeva kohta, annab kaks sobivat nõu, reageerib takistustele ja lepib kokku esimese sammu."}, "tags": {"003_d_move": "g_vocab", "003_t_exit": "g_vocab", "003_d_facts": "g_read", "003_d_think": "g_read", "003_p_reply": "g_notice", "003_p_sent": "g_notice", "003_t_advice": "g_use", "003_t_home": "g_use"}},
  "a2b1-004": {"canDo": "Ma helistan keelekooli, selgitan, miks mulle tunniaeg ei sobi, ja lepin viisakalt kokku uue aja.", "goals": {"g_vocab": "Õpilane kasutab kursuse ja aja sõnu: tunniaeg, sobima, muutma, vaba koht, registreeruma, hõivatud, internetis, kokku leppima.", "g_read": "Õpilane saab aru keelekooli automaatvastajast (päevad, kellaajad, vabad kohad, hind) ja valib endale sobiva aja.", "g_notice": "Õpilane valib kus-, kuhu- ja kust-vormi (tööl, koju, koosolekult) ja palub tingiva kõneviisiga (Kas te saaksite …? Kas sobiks …?).", "g_use": "Õpilane räägib minuti ilma abita oma nädalast, helistab administraatorile, reageerib takistusele ja lepib uue tunniaja kokku."}, "tags": {"004_d_now": "g_vocab", "004_t_exit": "g_vocab", "004_d_info": "g_read", "004_d_think": "g_read", "004_p_chat": "g_notice", "004_p_place": "g_notice", "004_p_sent": "g_notice", "004_t_phone": "g_use", "004_t_home": "g_use"}},
  "a2b1-005": {"canDo": "Ma loen lühikesi igapäevaseid tekste ja silte, kirjutan sõnumi ja kirja ning võrdlen tulemust lähtepunktiga.", "goals": {"g_read": "Õpilane valib igapäevases olukorras sobiva vastuse ja mõistab teateid trepikojas ja poes; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab kirjutades mooduli vorme: lihtminevik, osastav, ma- ja da-vorm, kohakäänded ja viisakas palve.", "g_use": "Õpilane kirjutab administraatorile sõnumi ja sõbrale kirja oma nädalast ning võrdleb tulemust tunni 1 lähtepunktiga."}, "tags": {}},
  "a2b1-006": {"canDo": "Ma kirjutan 30–60-sõnalise loo pildist oma perealbumist: kes on pildil ja kes nad mulle on (minu ema vend, õe tütar).", "goals": {"g_vocab": "Õpilane kasutab sugulussõnu: sugulane, suguvõsa, onu, tädi, nõbu, vanavanemad, lapselaps, põlvkond, abikaasa.", "g_read": "Õpilane saab aru tekstist „Üks pilt, kolm põlvkonda”: kes on kes ja kes on kellele sugulane, ning räägib sugupuu järgi.", "g_notice": "Õpilane moodustab omastava küsimusele kelle? (venna, õe, Igori, vanavanemate) ja kirjeldab sugulust: minu ema vend = onu.", "g_use": "Õpilane räägib ilma abita oma perest ja kirjutab 30–60-sõnalise loo pildist oma perealbumist; paariline küsib „Kelle …?”."}, "tags": {"006_d_cold": "g_vocab", "006_t_exit": "g_vocab", "006_d_text": "g_read", "006_d_read": "g_read", "006_d_tree": "g_read", "006_p_family": "g_notice", "006_p_sent": "g_notice", "006_t_story": "g_use", "006_t_home": "g_use"}},
  "a2b1-007": {"canDo": "Ma kirjeldan inimese välimust ja iseloomu kes-lausetega, lepin paarilisega kokku, keda soovitada, ja põhjendan oma valikut.", "goals": {"g_vocab": "Õpilane kasutab välimuse ja iseloomu sõnu: välimus, iseloom, habe, prillid, lokkis, kannatlik, rahulik, usaldama, igatsema, kartma.", "g_read": "Õpilane saab aru kuulutusest „Otsime lastele vanaema!”: millist inimest pere otsib ja miks.", "g_notice": "Õpilane ühendab laused kes-kõrvallausega (kes, kellel, keda, kellega) ja paneb kõrvallause ümber komad.", "g_use": "Õpilane kirjeldab inimest nii, et paariline ta pildilt ära tunneb, ja lepib kokku, keda perele soovitada."}, "tags": {"007_d_warm": "g_vocab", "007_t_exit": "g_vocab", "007_d_read": "g_read", "007_d_think": "g_read", "007_p_who": "g_notice", "007_p_sent": "g_notice", "007_t_choose": "g_use", "007_t_home": "g_use"}},
  "a2b1-008": {"canDo": "Ma helistan leitud asjade büroosse, kirjeldan oma kadunud asja mis-lausetega ja lepin kokku, kuidas ma selle kätte saan.", "goals": {"g_vocab": "Õpilane kasutab kaotamise ja leidmise sõnu: kaotama, leidma, unustama, kaduma, omanik, leitud asjad, sees, küljes, dokument.", "g_read": "Õpilane saab aru kohviku teatest „Leitud asjad”: mis on leitud, kus see on ja kuidas selle kätte saab.", "g_notice": "Õpilane eristab oma ja tema ning kirjeldab asja mis-lausega: kott, mille ma kaotasin; müts, millel on täht; asi, mis on laual.", "g_use": "Õpilane helistab büroosse, kirjeldab asja, reageerib ootamatule probleemile ja lepib kokku, millal ja kuidas asja kätte saab."}, "tags": {"008_d_warm": "g_vocab", "008_t_exit": "g_vocab", "008_d_found": "g_read", "008_d_think": "g_read", "008_p_call": "g_notice", "008_p_fix": "g_notice", "008_p_sent": "g_notice", "008_t_lost": "g_use", "008_t_home": "g_use"}},
  "a2b1-009": {"canDo": "Ma teen ettepaneku, põhjendan seda sest- või kuna-lausega, lepin pereliikmega peo plaani kokku ja kutsun häälsõnumiga päris inimese peole.", "goals": {"g_vocab": "Õpilane kasutab peo ja kokkuleppe sõnu: ettepanek, põhjus, kokku leppima, kokkulepe, kingitus, üllatus, külaline, kutse.", "g_read": "Õpilane saab aru häälsõnumist, kus tehakse peo kohta ettepanekuid ja põhjendatakse neid.", "g_notice": "Õpilane teeb ettepaneku (Teeme …! Võiksime …), põhjendab sest- või kuna-lausega ja sõnastab kokkuleppe: Lepime kokku, et …", "g_use": "Õpilane lepib pere nõupidamisel kokku peo plaani ja kutsub häälsõnumiga päris inimese peole."}, "tags": {"009_d_hook": "g_vocab", "009_t_exit": "g_vocab", "009_d_think": "g_read", "009_d_msg": "g_read", "009_p_why": "g_notice", "009_p_sent": "g_notice", "009_t_meet": "g_use", "009_t_invite": "g_use"}},
  "a2b1-010": {"canDo": "Ma saan aru pere teemalistest teadetest ja vestlustest, räägin ilma abita inimesest, kes on mulle tähtis, lepin kokku ja kirjutan lühikese sõnumi.", "goals": {"g_read": "Õpilane saab aru raadiovestlusest ja telefonisõnumist pere teemal; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: omastav, kes- ja mis-laused, oma, sest / kuna.", "g_use": "Õpilane räägib ilma abita inimesest, kes on talle tähtis, lepib kokku ja kirjutab sõnumi; võrdleb tulemust tunni 6 külma stardiga."}, "tags": {}},
  "a2b1-011": {"canDo": "Ma kirjeldan korterit liitega omadussõnadega, võrdlen kahte korterit ja kirjutan lähedasele 30–60-sõnalise sõnumi, kumma ma valin ja miks.", "goals": {"g_vocab": "Õpilane kasutab kodu ja üürimise sõnu: üürima, üür, omanik, korrus, ruumikas, valgusküllane, päikeseline, kodune, ohutu, ebamugav.", "g_read": "Õpilane saab aru kahest korterikuulutusest: milline korter on, mis on hea ja halb ning kumb sobib inimesele, ja räägib plaani järgi.", "g_notice": "Õpilane moodustab ja kasutab liitega omadussõnu: -ne / -line (kodune, päikeseline), -kas (ruumikas), -lik (rahulik), -tu (ohutu), eba- (ebamugav).", "g_use": "Õpilane räägib ilma abita oma kodust ja kirjutab lähedasele 30–60-sõnalise sõnumi, kumma korteri ta valib ja miks."}, "tags": {"011_d_cold": "g_vocab", "011_t_exit": "g_vocab", "011_d_open": "g_read", "011_d_read": "g_read", "011_d_plan": "g_read", "011_p_suffix": "g_notice", "011_p_sent": "g_notice", "011_t_mom": "g_use", "011_t_home": "g_use"}},
  "a2b1-012": {"canDo": "Ma saan aru häälsõnumist, kus asjad on ja kuhu need viia, lepin paarilisega kokku, kuhu mööbel läheb, ja kirjutan abilistele 30–60-sõnalise märkme.", "goals": {"g_vocab": "Õpilane kasutab kolimise sõnu: kolima, pakkima, kast, kandma, tõstma, kelder, aknalaud, riiul, kapp, abiline.", "g_read": "Õpilane saab aru häälsõnumist, kus asjad on, kust need võtta ja kuhu viia.", "g_notice": "Õpilane valib kus-, kuhu- ja kust-vormi (keldris – keldrisse – keldrist, voodi all – alla – alt, naabri juures – juurde – juurest) ja lühikese kuhu-vormi: tuppa, kööki, koju.", "g_use": "Õpilane lepib paarilisega kokku, kuhu mööbel läheb, kirjutab abilistele märkme ja leiab eesti.ee lehelt, kuidas elukohta registreerida."}, "tags": {"012_d_moves": "g_vocab", "012_t_exit": "g_vocab", "012_d_msg": "g_read", "012_d_where": "g_read", "012_p_markus": "g_notice", "012_p_sent": "g_notice", "012_t_note": "g_use", "012_t_home": "g_use"}},
  "a2b1-013": {"canDo": "Ma ütlen oma arvamuse linnaosa kohta, põhjendan seda sest- ja kuna-lausega ning lepin elanike koosolekul kokku, mida tühjale krundile teha.", "goals": {"g_vocab": "Õpilane kasutab linnaosa sõnu: linnaosa, elanik, krunt, mänguväljak, parkla, raamatukogu, koosolek, ettepanek, rahustav, puudu olema.", "g_read": "Õpilane saab aru elanike arvamustest raadios: kellele mis meeldib ja mis on puudu.", "g_notice": "Õpilane põhjendab arvamust sest- ja kuna-lausega (Kuna autosid on palju, ei ole tänav ohutu) ja kirjeldab kohta liitega omadussõnadega.", "g_use": "Õpilane ütleb koosolekul oma ettepaneku kahe põhjusega, vastab teise arvamusele ja lepib kokku ühe idee."}, "tags": {"013_d_opinion": "g_vocab", "013_t_exit": "g_vocab", "013_d_voices": "g_read", "013_d_think": "g_read", "013_p_why": "g_notice", "013_p_sent": "g_notice", "013_t_meeting": "g_use", "013_t_rec": "g_use"}},
  "a2b1-014": {"canDo": "Ma juhatan telefonis teed sõbrale (sina) ja võõrale (teie), küsin üle, kus inimene on, ja leian koos temaga õige tee.", "goals": {"g_vocab": "Õpilane kasutab tee juhatamise sõnu: ristmik, otse, pöörama, mööda, üle, läbi, maamärk, suletud, eksima, ümbersõit.", "g_read": "Õpilane saab aru kirjalikust teejuhisest: kuhu minna, kus pöörata ja mida mitte teha.", "g_notice": "Õpilane kasutab käskivat kõneviisi sõbrale ja võõrale (mine – minge, pööra – pöörake, ära mine – ärge minge) ja maamärke: kuni ristmikuni, mööda tänavat, üle tee, läbi pargi.", "g_use": "Õpilane juhatab telefonis eksinud külalist, küsib üle, kus ta on, ja lahendab ootamatu probleemi."}, "tags": {"014_d_first": "g_vocab", "014_t_exit": "g_vocab", "014_d_way": "g_read", "014_p_call": "g_read", "014_d_you": "g_notice", "014_p_sent": "g_notice", "014_t_call": "g_use", "014_t_home": "g_use"}},
  "a2b1-015": {"canDo": "Ma saan aru kodu ja linna teemalistest vestlustest ja sõnumitest, räägin ilma abita kohast, kus ma elan, lepin kokku ja kirjutan naabrile lühikese sõnumi.", "goals": {"g_read": "Õpilane saab aru raadiovestlusest ja telefonisõnumist kodu ja linna teemal; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: liitega omadussõnad, kus / kuhu / kust, sest / kuna, käskiv kõneviis.", "g_use": "Õpilane räägib ilma abita kohast, kus ta elab, lepib kokku ja kirjutab naabrile sõnumi; võrdleb tulemust tunni 11 külma stardiga."}, "tags": {}},
  "a2b1-016": {"canDo": "Ma loen ürituste kava, ütlen kellaaja ja kestuse ning lepin paarilisega kokku, mida me laupäeval koos teeme ja mis kell.", "goals": {"g_vocab": "Õpilane kasutab aja ja kava sõnu: kava, üritus, algama, kestma, veerand, kolmveerand, poolteist, hiljemalt, tasuta, end kirja panema.", "g_read": "Õpilane saab aru kultuurimaja avatud uste päeva kavast: mis kell midagi algab, kui kaua see kestab ja mida tuleb enne teha.", "g_notice": "Õpilane ütleb kellaaja (veerand, pool, kolmveerand), ajavahemiku (kella kümnest kella kuueni), kestuse (kestab kaks tundi) ning kasutab enne / pärast + osastavat ja kuni …-ni.", "g_use": "Õpilane lepib paarilisega pildi „Kaks laupäeva” järgi kokku laupäeva plaani ja leiab Peatus.ee lehelt, mis kell ja kui kaua ta sõidab."}, "tags": {"016_d_cold": "g_vocab", "016_t_exit": "g_vocab", "016_d_read": "g_read", "016_d_ask": "g_read", "016_p_case": "g_notice", "016_p_sent": "g_notice", "016_t_plan": "g_use", "016_t_home": "g_use"}},
  "a2b1-017": {"canDo": "Ma saan aru juhendist uuele töötajale ja kirjutan sõbrale 30–60-sõnalise sõnumi: mida ta tööl peab, võib ja ei tohi teha.", "goals": {"g_vocab": "Õpilane kasutab reeglite ja töö sõnu: reegel, kohustus, luba, keelatud, lubatud, juhataja, vahetus, tööriided, paus, haigeks jääma.", "g_read": "Õpilane saab aru juhataja häälsõnumist uuele töötajale: mis on kohustus, mis on lubatud ja mis on keelatud.", "g_notice": "Õpilane kasutab pean + ma-vormi ning võin, tohin, saan, tuleb, on vaja + da-vormi ja eristab ei pea (ei ole vaja) ja ei tohi (keelatud).", "g_use": "Õpilane kirjutab sõbrale 30–60-sõnalise sõnumi tema uue töö reeglitest ja seletab need ilma tekstita uuele paarilisele."}, "tags": {"017_d_rules": "g_vocab", "017_t_exit": "g_vocab", "017_d_brief": "g_read", "017_d_tell": "g_read", "017_p_forms": "g_notice", "017_p_sent": "g_notice", "017_t_letter": "g_use", "017_t_rec": "g_use"}},
  "a2b1-018": {"canDo": "Ma loen, mis on kiire ja mis võib oodata, otsustan paarilisega, mida teha esimesena, ja kirjutan pereliikmele 30–60-sõnalise märkme ühendverbidega.", "goals": {"g_vocab": "Õpilane kasutab ühendverbe ja nädala tööde sõnu: üles kirjutama, läbi lugema, ära maksma, ära koristama, edasi lükkama, ära jääma, kokku leppima, tähtaeg, nimekiri.", "g_read": "Õpilane saab aru tekstist „Nimekiri külmkapi uksel”: mis tuleb täna ära teha, mis võib oodata ja mis jääb ära.", "g_notice": "Õpilane paneb ühendverbi osakese õigesse kohta: Ma loen kirja läbi; Ma ei loe kirja läbi; Ma pean kirja läbi lugema; eituses osastav (ei maksnud arvet ära).", "g_use": "Õpilane otsustab paarilisega pildi „Nädala nimekiri” järgi, mis on kiire, ja kirjutab pereliikmele 30–60-sõnalise märkme."}, "tags": {"018_d_hook": "g_vocab", "018_t_exit": "g_vocab", "018_d_list": "g_read", "018_d_retell": "g_read", "018_p_place": "g_notice", "018_p_sent": "g_notice", "018_t_story": "g_use", "018_t_rec": "g_use"}},
  "a2b1-019": {"canDo": "Ma saan aru häälsõnumist, et minu aeg jääb ära, helistan registratuuri, keeldun viisakalt ja lepin kokku uue aja, mis mulle sobib.", "goals": {"g_vocab": "Õpilane kasutab aja kokkuleppimise sõnu: registratuur, vastuvõtt, aeg, sobima, vaba, ära jääma, edasi lükkama, kokku leppima, kahjuks, tagasi helistama.", "g_read": "Õpilane saab aru perearstikeskuse häälsõnumist: miks aeg jääb ära, millal on uued ajad ja mida kaasa võtta.", "g_notice": "Õpilane küsib viisakalt (kas sobiks …? kas teil oleks …? kas te saaksite …?), keeldub põhjusega (kahjuks …, sest / kuna …) ja kasutab ühendverbe ära jääma, edasi lükkama, kokku leppima.", "g_use": "Õpilane helistab registratuuri, reageerib ajale, mis ei sobi, ja lepib kokku uue aja; teisel korral lükkab ta sõbraga aja edasi."}, "tags": {"019_d_poll": "g_vocab", "019_t_exit": "g_vocab", "019_d_calls": "g_read", "019_d_what": "g_read", "019_p_join": "g_notice", "019_p_sent": "g_notice", "019_t_clinic": "g_use", "019_t_time": "g_use"}},
  "a2b1-020": {"canDo": "Ma saan aru ajast ja reeglitest teadetes, räägin ilma abita oma nädalavahetusest, lepin kokku aja ja kirjutan lühikese sõnumi, et mu plaan muutus.", "goals": {"g_read": "Õpilane saab aru spordiklubi teatest ja valib olukorda sobiva lause; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: kellaaeg ja kestus, enne / pärast, pean / võin / ei tohi, ühendverbid, viisakas -ks-vorm.", "g_use": "Õpilane räägib ilma abita oma nädalavahetusest, lepib kokku aja ja kirjutab sõbrale sõnumi; võrdleb tulemust tunni 16 külma stardiga."}, "tags": {}},
  "a2b1-021": {"canDo": "Ma saan aru kolleegi kirjast, mis tööl juhtus, ja kirjutan kaaslasele, kes oli nädal aega ära, 50–80-sõnalise sõnumi: mida me tegime ja mida veel ei teinud.", "goals": {"g_vocab": "Õpilane kasutab töönädala sõnu: puhkus, kolima, kast, ootama, parandama, klient, tutvustama, pakkumine, lubama, üle vaatama.", "g_read": "Õpilane saab aru kolleegi kirjast „Tere tulemast tagasi!”: mis igal päeval juhtus, mida tehti ja mida veel ei tehtud.", "g_notice": "Õpilane moodustab -si- ja -s-lihtmineviku kõigis isikutes (ootasin, ta ootas, me kolisime, ostsin) ja eituse ei …-nud osastavaga (ei saatnud pakkumist).", "g_use": "Õpilane kirjutab kaaslasele 50–80-sõnalise sõnumi nädala sündmustest ja räägib selle uuesti ilma tekstita."}, "tags": {"021_d_cold": "g_vocab", "021_t_exit": "g_vocab", "021_d_read": "g_read", "021_d_retell": "g_read", "021_p_forms": "g_notice", "021_p_sent": "g_notice", "021_t_letter": "g_use", "021_t_home": "g_use"}},
  "a2b1-022": {"canDo": "Ma räägin 60–90 sekundit, mida ma nädalavahetusel tegin, ja arutan paarilisega, kumb nädalavahetus oli parem puhkus.", "goals": {"g_vocab": "Õpilane kasutab mineviku ajasõnu ja nädalavahetuse sõnu: üleeile, eelmisel nädalal, … tagasi, kõigepealt, pärast seda, lõpuks, maale sõitma, end välja puhkama, näitus.", "g_read": "Õpilane saab aru raadioküsitlusest „Kuidas teie nädalavahetus möödus?”: kes mida millal tegi ja kes puhkas kõige rohkem.", "g_notice": "Õpilane alustab lauset ajasõnaga ja paneb tegusõna teisele kohale (Laupäeval käisin ma turul; Pärast seda käisime saunas), ka eituses.", "g_use": "Õpilane jutustab pildi „Kaks nädalavahetust” ja oma nädalavahetuse järgi 60–90 sekundit, arutab, kumb oli parem puhkus, ja räägib ERR Kultuuri uudisest."}, "tags": {"022_d_survey": "g_vocab", "022_t_exit": "g_vocab", "022_d_radio": "g_read", "022_d_tell": "g_read", "022_p_start": "g_notice", "022_p_sent": "g_notice", "022_t_debate": "g_use", "022_t_home": "g_use"}},
  "a2b1-023": {"canDo": "Ma räägin telefonis, kus ma festivalil käisin ja mida tegin (läksin, sõin, nägin), ja saan teada, kust oma kaotatud asja kätte saan.", "goals": {"g_vocab": "Õpilane kasutab festivali sõnu: festival, lava, telk, järjekord, käepael, käsitöö, infotelk, pink, kaotama, maha jääma.", "g_read": "Õpilane saab aru blogist „Meie päev Jõe festivalil”: kus pere käis, mida nad sõid, nägid ja tegid ning kust müts leiti.", "g_notice": "Õpilane moodustab -i-lihtmineviku ja sagedased erandid (tulin, sain, jäin, sõin, jõin, tõin, läksin, tegin, nägin, panin) ning eituse: ei tulnud, ei läinud, ei näinud.", "g_use": "Õpilane jutustab telefonis pildi „Festivali kaart” järgi oma tee, kirjeldab kaotatud kotti, reageerib varjatud infole ja lepib kokku, kuidas asja kätte saab."}, "tags": {"023_d_opinion": "g_vocab", "023_t_exit": "g_vocab", "023_d_board": "g_read", "023_d_retell": "g_read", "023_p_forms": "g_notice", "023_p_sent": "g_notice", "023_t_office": "g_use", "023_t_talk": "g_use"}},
  "a2b1-024": {"canDo": "Ma kirjutan raamatukogu lugude võistlusele 50–80-sõnalise loo „Minu ootamatu päev”: algus, probleem, mis edasi juhtus ja lõpp.", "goals": {"g_vocab": "Õpilane kasutab loo sõnu: alguses, äkki, märkama, kaduma, mures, õnneks, kahjuks, lõpuks, võõras, võistlus.", "g_read": "Õpilane saab aru raadioloost „Kuulaja lugu”: mis juhtus, mis järjekorras ja kuidas lugu lõppes.", "g_notice": "Õpilane seob laused looks (kui-lause, sest, nii … et, äkki, õnneks, lõpuks) ja paneb loo sõna järel tegusõna teisele kohale.", "g_use": "Õpilane kirjutab võistlusele 50–80-sõnalise loo (oma lugu või pildi „Neli pilti” järgi), loeb selle paarilisele kui žüriile ja parandab teise versiooni."}, "tags": {"024_d_idea": "g_vocab", "024_t_exit": "g_vocab", "024_d_anna": "g_read", "024_d_retell": "g_read", "024_d_join": "g_notice", "024_p_draft": "g_notice", "024_t_story": "g_use", "024_t_rec": "g_use"}},
  "a2b1-025": {"canDo": "Ma saan aru, kui inimesed räägivad sellest, mis juhtus, räägin ilma abita ühest erilisest päevast, jutustan sõbrale, mis juhtus, ja kirjutan lühikese sõnumi minevikus.", "goals": {"g_read": "Õpilane saab aru raadiointervjuust ja häälsõnumist sellest, mis juhtus; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: lihtminevik -si- / -s- ja -i-, sagedased erandid, eitus ei …-nud, ajasõna ees → tegusõna teisel kohal, loo sõnad.", "g_use": "Õpilane räägib ilma abita ühest erilisest päevast, jutustab sõbrale väljasõidust ja kirjutab sõnumi nädalavahetusest; võrdleb tulemust tunni 21 külma stardiga."}, "tags": {}},
  "a2b1-026": {"canDo": "Ma kirjutan kaaslasele 50–80-sõnalise sõnumi: mida ja kui palju poest osta.", "goals": {"g_vocab": "Õpilane kasutab toidu ja koguse sõnu: toiduaine, kogus, nimekiri, külmkapp, pakk, värske, liiter, köögivili, puuvili, kokku hoidma.", "g_read": "Õpilane saab aru tekstist „Kuidas me toiduraha kokku hoiame”: mida pere enne poodi teeb, kuidas nimekiri on kirjutatud ja kui palju raha nad kokku hoiavad.", "g_notice": "Õpilane kasutab koguse järel osastavat (liiter piima, pakk võid, kilo kartuleid, palju õunu) ja arvu järel ainsuse osastavat (kuus muna; aga üks muna).", "g_use": "Õpilane kirjutab kaaslasele 50–80-sõnalise sõnumi pildi „Külmkapp ja retsept” või oma menüü järgi: mis kodus on, mida ja kui palju osta, ning ütleb nimekirja ilma tekstita."}, "tags": {"026_d_cold": "g_vocab", "026_t_exit": "g_vocab", "026_d_read": "g_read", "026_d_retell": "g_read", "026_p_forms": "g_notice", "026_p_sent": "g_notice", "026_t_letter": "g_use", "026_t_home": "g_use"}},
  "a2b1-027": {"canDo": "Ma helistan restorani, broneerin laua, küsin taimetoidu ja allergia kohta ning lepin kokku, kui midagi ei sobi.", "goals": {"g_vocab": "Õpilane kasutab restorani sõnu: broneerima, saal, täis, taimetoit, allergia, pähklid, eelroog, praad, magustoit, sobima.", "g_read": "Õpilane saab aru telefonikõnest restoraniga: mitmele ja millal laud broneeritakse, mida saab süüa taimetoitlane ja pähkliallergiaga laps.", "g_notice": "Õpilane palub viisakalt (Ma sooviksin …, Kas ma saaksin …?, Kas … sobiks?, Kas te võiksite …?) ja kasutab -ks-vormi: eelroaks, pearoaks, joogiks, magustoiduks.", "g_use": "Õpilane helistab pildi „Restorani menüü” järgi restorani, broneerib oma seltskonnale laua, reageerib varjatud infole ja kordab kokkuleppe üle."}, "tags": {"027_d_survey": "g_vocab", "027_t_exit": "g_vocab", "027_d_lunch": "g_read", "027_d_retell": "g_read", "027_p_ks": "g_notice", "027_p_sent": "g_notice", "027_t_call": "g_use", "027_t_home": "g_use"}},
  "a2b1-028": {"canDo": "Ma räägin 60–90 sekundit, mis meie köögis nädala jooksul juhtus (mida sõime ära ja mida viskasime ära), ja arutan paarilisega, kuidas vähem toitu raisata.", "goals": {"g_vocab": "Õpilane kasutab köögi ja toidu raiskamise sõnu: ära sööma, ära viskama, raiskama, üle jääma, karp, pott, hapu, pehme, prügikast, kaste.", "g_read": "Õpilane saab aru päevikust „Meie toidunädal”: mida pere ostis, mida sõi ära, mis jäi üle ja mida pidi ära viskama.", "g_notice": "Õpilane eristab osastavat ja täissihitist: sõime suppi ↔ sõime supi ära, ostsin leiva, viskasime tomatid ära; eituses on alati osastav: ei ostnud leiba.", "g_use": "Õpilane jutustab pildi „Kaks külmkappi pühapäeval” ja oma köögi järgi 60–90 sekundit, arutab, kumb kodu raiskab vähem, annab nõu ja räägib Toidupanga lehest."}, "tags": {"028_d_warm": "g_vocab", "028_t_exit": "g_vocab", "028_d_diary": "g_read", "028_d_retell": "g_read", "028_p_forms": "g_notice", "028_p_sent": "g_notice", "028_t_meeting": "g_use", "028_t_home": "g_use"}},
  "a2b1-029": {"canDo": "Ma kirjutan firmale 50–80-sõnalise viisaka kaebuse: mis valesti läks ja mida ma soovin.", "goals": {"g_vocab": "Õpilane kasutab kaebuse sõnu: tellimus, kuller, klienditeenindus, kaebus, hilinema, raha tagasi, allahindlus, vabandama, kinnitus, arvustus.", "g_read": "Õpilane saab aru kliendi kõnest klienditeenindusse: mida klient tellis ja sai, mis veel valesti läks, mida ta palus ja mida firma pakkus.", "g_notice": "Õpilane kaebab nelja sammuga (tervitus ja tellimus, probleem, palve, tänu) ja kasutab kaebuse vorme: tellisin kaks pitsat, sain ühe pitsa, salatit ei saanud, ma sooviksin.", "g_use": "Õpilane kirjutab firmale pildi „Mis tuli koju?” või oma kogemuse järgi 50–80-sõnalise kaebuse, loeb selle klienditeenindajale ette ja parandab teise versiooni."}, "tags": {"029_d_story": "g_vocab", "029_t_exit": "g_vocab", "029_d_call": "g_read", "029_d_retell": "g_notice", "029_p_where": "g_read", "029_p_sent": "g_notice", "029_t_reply": "g_use", "029_t_rec": "g_use"}},
  "a2b1-030": {"canDo": "Ma saan aru toidu ja teeninduse kuulutustest ja lühikesest tekstist, räägin ilma abita ühest söögikorrast, tellin telefonis toitu ja kirjutan lühikese sõnumi.", "goals": {"g_read": "Õpilane leiab olukorrale sobiva kuulutuse ja saab aru maja teatest jagamiskapi kohta; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: kogus + osastav, arv + ainsuse osastav, täis- ja osasihitis, eituses osastav, viisakas -ksin ja -ks.", "g_use": "Õpilane räägib ilma abita ühest söögikorrast, tellib telefonis kohvikust toitu ja kirjutab naabrile sõnumi; võrdleb tulemust tunni 26 külma stardiga."}, "tags": {}},
  "a2b1-031": {"canDo": "Ma kirjutan juhile 50–80-sõnalise sõnumi: et jäin haigeks, mis muutus, kui kauaks jään koju ja kes teeb minu töö.", "goals": {"g_vocab": "Õpilane kasutab haiguse sõnu: haige, terve, palavik, köha, nohu, kurk, valutama, perearst, nõuandeliin, haigusleht.", "g_read": "Õpilane saab aru tekstist „Mida teha, kui jääd haigeks?”: millal piisab kodusest ravist, millal helistada perearstikeskusesse, 1220 või 112 ja mida öelda juhile.", "g_notice": "Õpilane eristab olekut ja muutust: olen haige ↔ jäin haigeks, palavik läks kõrgeks, sain terveks (omastav + -ks).", "g_use": "Õpilane kirjutab juhile pildi „Minu kolm päeva” või oma olukorra järgi 50–80-sõnalise sõnumi: mis juhtus ja muutus, kui kauaks ta koju jääb ja kes teeb tema töö."}, "tags": {"031_d_cold": "g_vocab", "031_t_exit": "g_vocab", "031_d_read": "g_read", "031_d_retell": "g_read", "031_p_forms": "g_notice", "031_p_sent": "g_notice", "031_t_letter": "g_use", "031_t_rec": "g_use"}},
  "a2b1-032": {"canDo": "Ma helistan perearstikeskusesse, räägin, kuidas mu haigus on muutunud, ja lepin kokku sobiva aja.", "goals": {"g_vocab": "Õpilane kasutab arsti juurde aja saamise sõnu: registratuur, vastuvõtt, vaba aeg, pereõde, kestma, kähe, hingamine, tugev, hullem, isikukood.", "g_read": "Õpilane saab aru patsiendi kõnest perearstikeskusesse: kuidas haigus muutus, miks pakutud aeg ei sobinud ja mis aeg lõpuks kokku lepiti.", "g_notice": "Õpilane kasutab muutuse tegusõnu -ks-vormiga: jäi kähedaks, läks kõrgeks, muutus tugevamaks, läks hullemaks, sai terveks.", "g_use": "Õpilane helistab pildi „Perearstikeskuse nädal” järgi registratuuri, ütleb, kuidas haigus muutus, reageerib varjatud infole ja kordab kokkuleppe üle."}, "tags": {"032_d_warm": "g_vocab", "032_t_exit": "g_vocab", "032_d_visit": "g_read", "032_d_retell": "g_read", "032_p_where": "g_read", "032_d_model": "g_notice", "032_p_sent": "g_notice", "032_t_appt": "g_use", "032_t_rec": "g_use"}},
  "a2b1-033": {"canDo": "Ma räägin paarilisega, kuidas paremini magada: annan 60–90 sekundit nõu (pane telefon ära, ära joo õhtul kohvi) ja lepime kokku nädala plaani.", "goals": {"g_vocab": "Õpilane kasutab une sõnu: uni, magama jääma, ärkama, väsinud, ekraan, valgus, pime, jahe, rahulik, nõu andma.", "g_read": "Õpilane saab aru tekstist „Viis nõuannet hea une jaoks”: mida teha ja mida mitte ning millal pöörduda perearsti poole.", "g_notice": "Õpilane annab nõu käskivas kõneviisis: sina — mine, pane, joo, ära joo; teie — minge, pange, jooge, ärge jooge.", "g_use": "Õpilane annab pildi „Kaks õhtut” järgi paarilisele nõu, põhjendab, lepib kokku nädala plaani ja räägib päris lehest „Parema une nõuanded”."}, "tags": {"033_d_warm": "g_vocab", "033_t_exit": "g_vocab", "033_d_sleep": "g_read", "033_d_retell": "g_read", "033_p_forms": "g_notice", "033_d_model": "g_notice", "033_p_sent": "g_notice", "033_t_advice": "g_use", "033_t_home": "g_use"}},
  "a2b1-034": {"canDo": "Ma kirjutan infolehte 50–80-sõnalise loo: mis harjumust ma kuu aega muutsin, kuidas see läks ja mis muutus.", "goals": {"g_vocab": "Õpilane kasutab harjumuste sõnu: harjumus, liikuma, trenn, ujuma, trepp, magus, loobuma, tegelema, alla andma, tuju.", "g_read": "Õpilane saab aru raadiosaatest „30 päeva tervemalt”: mida kolm kuulajat muutsid, mis oli raske ja mis läks paremaks.", "g_notice": "Õpilane kasutab harjumuse vorme: käin ujumas, hakkasin jooksma, tegelen joogaga, loobusin magusast, uni läks paremaks.", "g_use": "Õpilane kirjutab pildi „Minu 30 päeva” või oma harjumuse järgi infolehte 50–80-sõnalise loo, loeb selle toimetajale ette ja parandab teise versiooni."}, "tags": {"034_d_warm": "g_vocab", "034_t_exit": "g_vocab", "034_d_talk": "g_read", "034_d_retell": "g_read", "034_p_forms": "g_notice", "034_p_free": "g_notice", "034_t_story": "g_use", "034_t_rec": "g_use"}},
  "a2b1-035": {"canDo": "Ma saan aru raadiointervjuust ja häälsõnumist tervise teemal, räägin ilma abita ühest korrast, kui olin haige, helistan perearstikeskusesse ja kirjutan sõbrale lühikese sõnumi.", "goals": {"g_read": "Õpilane saab aru intervjuust nõuandeliini õega ja treeneri häälsõnumist; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: olek ja muutus, -ks (läks hullemaks, sai terveks), käskiv kõneviis, käin ujumas, loobusin magusast.", "g_use": "Õpilane räägib ilma abita ühest korrast, kui ta oli haige, helistab perearstikeskusesse ja kirjutab sõbrale sõnumi; võrdleb tulemust tunni 31 külma stardiga."}, "tags": {}},
  "a2b1-036": {"canDo": "Ma helistan huvijuhile, ütlen, millest laps huvitub ja milles ta osaleda tahab, küsin ringide kohta ja panen lapse kirja.", "goals": {"g_vocab": "Õpilane kasutab kooli ja huviringide sõnu: huvituma, osalema, harjuma, valmistuma, sõltuma, huviring, huvijuht, klassijuhataja, hinne, kontrolltöö.", "g_read": "Õpilane saab aru tekstist „Kool ja huviringid Eestis”: kui kaua kestab põhikool, mis hinded on, mida teevad klassijuhataja ja huvijuht ning kellelt abi paluda.", "g_notice": "Õpilane kasutab tegusõna koos õige käändega: huvitub millest (-st), osaleb milles (-s), harjub millega (-ga), valmistub milleks (-ks), palub abi kellelt (-lt); muret kelle pärast.", "g_use": "Õpilane helistab pildi „Kooli huviringid” järgi huvijuhile, ütleb, millest laps huvitub, reageerib varjatud infole ja paneb lapse ringi kirja; teisel katsel helistab enda pärast."}, "tags": {"036_d_cold": "g_vocab", "036_t_exit": "g_vocab", "036_d_read": "g_read", "036_d_retell": "g_read", "036_p_forms": "g_notice", "036_p_sent": "g_notice", "036_t_ring": "g_use", "036_t_rec": "g_use"}},
  "a2b1-037": {"canDo": "Ma kirjutan sõbrale 50–80-sõnalise sõnumi oma õppimisplaanist: mida ma pean ja tahan õppida ning kuidas ma õpin.", "goals": {"g_vocab": "Õpilane kasutab õppimise sõnu: eesmärk, tase, eksam, sooritama, kursus, kordama, harjutama, meelde jätma, julgelt, keelekohvik.", "g_read": "Õpilane saab aru raadiosaatest „Kuidas täiskasvanud keelt õpivad?”: miks ja kuidas kaks inimest õpivad, mis on raske ja mida nad soovitavad.", "g_notice": "Õpilane valib ma- või da-vormi: pean, hakkan, lähen + ma-vorm; tahan, oskan, proovin, kardan, meeldib, on vaja + da-vorm; teha, minna, tulla.", "g_use": "Õpilane kirjutab pildi „Minu õppimisnädal” või oma plaani järgi sõbrale 50–80-sõnalise sõnumi oma eesmärgist ja õppimisest, loeb selle ette ja parandab teise versiooni."}, "tags": {"037_d_warm": "g_vocab", "037_t_exit": "g_vocab", "037_d_radio": "g_read", "037_d_retell": "g_read", "037_p_forms": "g_notice", "037_p_sent": "g_notice", "037_t_letter": "g_use", "037_t_rec": "g_use", "037_d_model": "g_notice"}},
  "a2b1-038": {"canDo": "Ma räägin paarilisega, kuidas on kõige parem keelt õppida: põhjendan (sest, kuna, seepärast) ja lepime kokku, mida proovida.", "goals": {"g_vocab": "Õpilane kasutab põhjuse ja õppimisviiside sõnu: põhjus, tagajärg, sest, kuna, seepärast, rühm, üksi, äpp, keelesõber, mugav.", "g_read": "Õpilane saab aru raadiosaatest keeleõpetajaga: miks on kursus, äpp ja keelesõber kasulikud, miks õppida iga päev natuke ja miks vigu ei tasu karta.", "g_notice": "Õpilane ütleb põhjuse ja tagajärje õige sõnajärjega: …, sest ma tahan; Kuna mul on vähe aega, õpin ma …; …, seepärast õpin ma ….", "g_use": "Õpilane arutab pildi „Kolm võimalust” järgi paarilisega, mis õppimisviis sobib, põhjendab, lepib kokku, mida proovida, ja räägib päris lehest „Ülevaade õppevõimalustest”."}, "tags": {"038_d_warm": "g_vocab", "038_t_exit": "g_vocab", "038_d_retell": "g_read", "038_p_forms": "g_notice", "038_d_model": "g_notice", "038_t_choose": "g_use", "038_t_rec": "g_use", "038_d_radio": "g_read"}},
  "a2b1-039": {"canDo": "Ma kirjutan kursuse õpetajale 50–60-sõnalise e-kirja: miks ma tundidest puudusin, mis jäi tegemata ja millist abi ma viisakalt palun.", "goals": {"g_vocab": "Õpilane kasutab kursuse ja mahajäämise sõnu: maha jääma, puuduma, järele jõudma, materjal, kodutöö, konsultatsioon, keskenduma, muretsema, tähtaeg, tänulik.", "g_read": "Õpilane saab aru õpetaja e-kirjast: millest õppija puudus, millal on kontrolltöö, kus on materjalid, millal saata kodutöö ja millele keskenduda; küsib telefonis õpetajalt sama.", "g_notice": "Õpilane kasutab tegusõna koos käändega (puudusin tunnist, jäin kursusest maha, keskendun grammatikale, palun abi õpetajalt) ja viisakat palvet (Kas te saaksite …? Kas ma võiksin …?).", "g_use": "Õpilane vastab pildi „Minu kursus: mis jäi tegemata?” või oma olukorra järgi õpetajale 50–60-sõnalise viisaka e-kirjaga ja ütleb sama telefonis ilma tekstita."}, "tags": {"039_d_warm": "g_vocab", "039_t_exit": "g_vocab", "039_d_retell": "g_read", "039_p_forms": "g_notice", "039_p_sent": "g_notice", "039_t_reply": "g_use", "039_t_rec": "g_use", "039_d_mail": "g_read", "039_d_model": "g_notice"}},
  "a2b1-040": {"canDo": "Ma saan aru kursuste ja ringide kuulutustest ning kooli teatest, räägin ilma abita oma õppimisest, helistan keelekooli ja kirjutan klassijuhatajale lühikese sõnumi.", "goals": {"g_read": "Õpilane leiab olukorrale sobiva kursuse või ringi kuulutuse ja saab aru kooli teatest lapsevanematele; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: tegusõna + kääne, ma- või da-vorm, sest / kuna / seepärast, viisakas palve -ksite / -ksin.", "g_use": "Õpilane räägib ilma abita oma õppimisest, helistab keelekooli ja kirjutab klassijuhatajale sõnumi; võrdleb tulemust tunni 36 külma stardiga."}, "tags": {}},
  "a2b1-041": {"canDo": "Ma räägin oma tööst või tööst, mida tahaksin teha: kellena töötan, mille eest vastutan ja millega iga päev tegelen.", "goals": {"g_vocab": "Õpilane kasutab ametite ja töö sõnu: amet, töökoht, vastutama, hoolitsema, tegelema, vahetus, tööaeg, palk, ladu, tulemus.", "g_read": "Õpilane saab aru tekstist „Kell kuus hommikul”: kellena neli inimest töötavad, mille eest nad vastutavad ja millega tegelevad.", "g_notice": "Õpilane kasutab ametit ja tegusõna õiges vormis: töötab kokana (-na), sai kokaks (-ks), vastutab köögi eest, hoolitseb laste eest (omastav + eest), tegeleb klientidega (-ga).", "g_use": "Õpilane kirjeldab mängus „Arva ära amet” pildi „Kuus ametit” järgi ametit nime ütlemata ja räägib teisel korral ilma fraasideta oma päris tööst."}, "tags": {"041_d_cold": "g_vocab", "041_t_exit": "g_vocab", "041_d_story": "g_read", "041_d_retell": "g_read", "041_p_forms": "g_notice", "041_p_sent": "g_notice", "041_t_doubt": "g_use", "041_t_rec": "g_use"}},
  "a2b1-042": {"canDo": "Ma räägin töö juures telefonis: ütlen, kus kolleeg on ja millal ta tagasi tuleb (on kohtumas, tuleb söömast), ja võtan sõnumi vastu.", "goals": {"g_vocab": "Õpilane kasutab kontori ja telefoni sõnu: vastuvõtt, koosolek, koolitus, ladu, klient, tellimus, arve, sõnum, tagasi helistama, kohtumine.", "g_read": "Õpilane saab aru kolmest lühikesest kõnest vastuvõttu: kus kolleeg on, millal ta tagasi tuleb ja mis jäi tegemata.", "g_notice": "Õpilane kasutab ma-vormi käändes: läks kontrollima (-ma), on kohtumas (-mas), tuleb söömast (-mast), jäi saatmata (-mata).", "g_use": "Õpilane vastab pildi „Kes kus on?” järgi telefonile, reageerib helistaja varjatud infole, kirjutab sõnumi üles ja lepib kokku tagasihelistamise."}, "tags": {"042_d_warm": "g_vocab", "042_t_exit": "g_vocab", "042_d_calls": "g_read", "042_d_retell": "g_read", "042_p_forms": "g_notice", "042_p_sent": "g_notice", "042_p_gap": "g_use", "042_t_rec": "g_use"}},
  "a2b1-043": {"canDo": "Ma kirjutan töökuulutusele 60–90-sõnalise kandideerimiskirja: millisele kohale kandideerin, mida oskan ja olen harjunud tegema, miks töö mulle sobib ja millal saan alustada.", "goals": {"g_vocab": "Õpilane kasutab kandideerimise sõnu: kandideerima, ametikoht, kogemus, oskus, tööandja, sobima, alustama, olen harjunud, olen valmis, lugupidamisega.", "g_read": "Õpilane saab aru kandideerimiskirjast: mis on igas lõigus, mida kandidaat oskab ja millal saab alustada; miks kiri on ametlik.", "g_notice": "Õpilane valib tööverbi järel ma- või da-vormi: olen harjunud töötama, olen valmis õppima, käisin kursusel õppimas ↔ oskan kasutada, soovin töötada, mulle meeldib suhelda.", "g_use": "Õpilane kirjutab pildi „Kaks töökuulutust” või päris kuulutuse järgi 60–90-sõnalise kandideerimiskirja ilma antud alguseta ja räägib kodus päris tööpakkumisest Töötukassa lehel."}, "tags": {"043_d_warm": "g_vocab", "043_t_exit": "g_vocab", "043_d_model": "g_read", "043_d_retell": "g_read", "043_p_forms": "g_notice", "043_p_sent": "g_notice", "043_t_letter": "g_use", "043_t_rec": "g_use"}},
  "a2b1-044": {"canDo": "Ma vastan töövestlusel küsimustele 3–4 lausega (väide, näide, seos), küsin ise kaks küsimust ja ütlen, millal saan alustada.", "goals": {"g_vocab": "Õpilane kasutab töövestluse sõnu: tugevus, nõrkus, näide, täpne, meeskond, juhendama, katseaeg, kandidaat, tööle võtma, kokkulepe.", "g_read": "Õpilane saab aru töövestluse salvestusest: kandidaadi kogemus, tugevus koos näitega, nõrkus, tema küsimused ja töö vahetused.", "g_notice": "Õpilane ehitab vastuse väitest, näitest ja seosest (Olen täpne. Näiteks … Seepärast …) ning kasutab vorme olen harjunud töötama, käisin õppimas, ei jäänud täitmata, Kes mind juhendama hakkab?", "g_use": "Õpilane teeb pildi „Töövestlus” järgi paaris töövestluse kandidaadi ja tööandjana, tööandja otsustab ja põhjendab; teisel korral räägib õpilane oma päris tööst."}, "tags": {"044_d_warm": "g_vocab", "044_t_exit": "g_vocab", "044_d_listen": "g_read", "044_d_retell": "g_read", "044_p_forms": "g_notice", "044_p_sent": "g_notice", "044_t_job": "g_use", "044_t_rec": "g_use"}},
  "a2b1-045": {"canDo": "Ma saan aru töö juures kuuldud teadetest ja raadiojutust, räägin ilma abita oma tööst, vastan töövestlusel ja kirjutan kolleegidele teate.", "goals": {"g_read": "Õpilane saab aru töö juures kuuldud lühikestest teadetest ja raadiojutust suvetööst; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: kellena -na, mille eest, millega -ga, ma-vorm käändes, ma- või da-vorm tööverbi järel.", "g_use": "Õpilane räägib ilma abita oma tööst, vastab töövestlusel õpetajale ja kirjutab kolleegidele 60–80-sõnalise teate; võrdleb tulemust tunni 41 külma stardiga."}, "tags": {"045_t_l1": "g_read", "045_t_l2": "g_read", "045_t_s1": "g_use", "045_t_interview": "g_use", "045_p_w1": "g_notice"}},
  "a2b1-046": {"canDo": "Ma küsin ja annan sõiduinfot: kust ja mis kell rong või buss väljub, kus tuleb ümber istuda ning kuhu ja millal see jõuab.", "goals": {"g_vocab": "Õpilane kasutab sõiduinfo sõnu: väljuma, saabuma, ümber istuma, perroon, sõiduplaan, ühendus, ära jääma, asendusbuss, pagasiruum, edasi-tagasi pilet.", "g_read": "Õpilane saab aru kolmest kõnest reisiinfosse: kust ja mis kell sõiduk väljub, kus tuleb ümber istuda, kuhu ja millal see jõuab ning mis jäi ära.", "g_notice": "Õpilane kasutab sõiduinfos kohavorme: väljub Tallinnast, perroonilt (kust?), istub ümber Tapal, ootab jaamas (kus?), saabub Tartusse, sõidab Võrru (kuhu?).", "g_use": "Õpilane vastab pildi „Sõiduplaan: Tallinn → Tartu” järgi reisiinfo telefonile, reageerib helistaja varjatud infole ja leiab talle parima ühenduse; kodus otsib päris ühenduse Peatus.ee lehelt."}, "tags": {"046_d_cold": "g_vocab", "046_t_exit": "g_vocab", "046_d_call": "g_read", "046_d_retell": "g_read", "046_p_forms": "g_notice", "046_p_sent": "g_notice", "046_p_gap": "g_use", "046_t_rec": "g_use"}},
  "a2b1-047": {"canDo": "Ma räägin, millega reisida: võrdlen kahte-kolme reisiviisi (odavam, kiirem, mugavam) ja põhjendan, mida eelistan.", "goals": {"g_vocab": "Õpilane kasutab reisiviiside võrdlemise sõnu: odav, kallis, kiire, mugav, lend, lennujaam, pistikupesa, ruum, eelistama, pigem.", "g_read": "Õpilane saab aru tekstist „Kolm teed Riiga”: mis on bussi, rongi, lennuki ja auto pluss ja miinus ning mida autor soovitab.", "g_notice": "Õpilane võrdleb ja valib: odavam kui, kõige kiirem, eelistan rongi bussile (osastav + -le), pigem … kui, kumb, mõlemad; leiab fraasid tekstis (Harno B1 lugemine 4).", "g_use": "Õpilane arutab paaris pildi „Kolm teed Riiga” järgi, millega sõita, põhjendab ja jõuab eelarve piires ühe otsuseni; teisel korral räägib ilma fraasideta oma järgmisest reisist."}, "tags": {"047_d_warm": "g_vocab", "047_t_exit": "g_vocab", "047_d_blog": "g_read", "047_d_retell": "g_read", "047_p_forum": "g_notice", "047_p_sent": "g_notice", "047_t_agree": "g_use", "047_t_rec": "g_use"}},
  "a2b1-048": {"canDo": "Ma räägin reisist, mis läks teisiti: mis juhtus ja mis oli enne juhtunud (praam oli juba lahkunud, olin telgi unustanud).", "goals": {"g_vocab": "Õpilane kasutab reisiloo sõnu: sadam, praam, lahkuma, jõudma, unustama, selguma, käivituma, telk, õnneks, kahjuks.", "g_read": "Õpilane saab aru raadioloost „Teel juhtunud”: mis juhtus enne ja mis pärast, ning otsustab, kas väide on õige või vale (Harno B1 kuulamine 4).", "g_notice": "Õpilane kasutab enneminevikku: oli lahkunud, olin unustanud, polnud broneerinud; Kui me jõudsime, oli … juba …", "g_use": "Õpilane jutustab mängus pildiloo „Reis Riiga” enneminevikuga ja teisel ringil ilma fraasideta oma reisist, mis läks teisiti."}, "tags": {"048_d_warm": "g_vocab", "048_t_exit": "g_vocab", "048_p_radio": "g_read", "048_d_retell": "g_read", "048_p_forms": "g_notice", "048_d_write": "g_notice", "048_t_live": "g_use", "048_t_rec": "g_use"}},
  "a2b1-049": {"canDo": "Ma kirjutan sõbrale 60–90-sõnalise kirja kahe päeva plaaniga: kuidas ta sõidab, kus ööbib, mida teeme ja üks hea nõuanne.", "goals": {"g_vocab": "Õpilane kasutab reisiplaani sõnu: külla tulema, ööbima, vaatamisväärsus, näitus, soovitama, tasub, hoiatus, suletud, mugavad jalanõud, jaama vastu tulema.", "g_read": "Õpilane saab aru sõbra kirjast „Kaks päeva Tartus”: sõit, ööbimine, plaan päevade kaupa, nõuanne ja hoiatus.", "g_notice": "Õpilane kasutab nõuandes da-vormi (soovitan sõita, tasub vaadata, ära unusta võtta, võid osta) ja hoiatuses enneminevikku (olime unustanud, et …).", "g_use": "Õpilane kirjutab pildi „Kaks päeva Pärnus” või oma linna järgi sõbrale 60–90-sõnalise isikliku kirja ilma antud alguseta (Harno B1 kirjutamine 2b nurk)."}, "tags": {"049_d_warm": "g_vocab", "049_t_exit": "g_vocab", "049_d_guide": "g_read", "049_d_retell": "g_read", "049_p_forms": "g_notice", "049_p_sent": "g_notice", "049_t_letter": "g_use", "049_t_rec": "g_use"}},
  "a2b1-050": {"canDo": "Ma saan aru reisiteenuste kuulutustest ja teatest reisijatele, räägin ilma abita ühest reisist, helistan hostelisse ja kirjutan sõbrale sõnumi.", "goals": {"g_read": "Õpilane leiab olukorrale sobiva reisiteenuse kuulutuse ja saab aru teatest reisijatele; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: kust / kus / kuhu sõiduinfos, võrdlus ja valik, enneminevik, nõuanne da-vormiga.", "g_use": "Õpilane räägib ilma abita ühest reisist, helistab hostelisse ja kirjutab sõbrale 60–80-sõnalise sõnumi; võrdleb tulemust tunni 46 külma stardiga."}, "tags": {"050_p_r1": "g_read", "050_p_r2text": "g_read", "050_t_s1": "g_use", "050_t_s2": "g_use", "050_t_w1": "g_notice"}},
  "a2b1-051": {"canDo": "Ma küsin poes hinda, soodustust, värvi ja suurust, arvutan, kui palju ost kokku maksab, ja ostan eelarve piires.", "goals": {"g_vocab": "Õpilane kasutab ostlemise sõnu: hind, soodustus, pakkumine, poole hinnaga, suurus, garantii, tšekk, kliendikaart, tagastama, kokku.", "g_read": "Õpilane saab aru poe nädala pakkumistest: mis on mitu protsenti odavam, mis värvi ja suuruses kaupa on, kuidas maksta ja tagastada.", "g_notice": "Õpilane küsib poes varianti ja soodustust: Kas seda on ka sinisena? (-na), suuruses M, 30 % odavam, poole hinnaga, 20 protsenti soodustust.", "g_use": "Õpilane ostab pildi „Hinnasildid” järgi sõbrale kingituse 60 euro eest, reageerib müüja varjatud infole ja ütleb, kui palju ost kokku teeb."}, "tags": {"051_d_best": "g_vocab", "051_t_exit": "g_vocab", "051_d_ad": "g_read", "051_d_ask": "g_read", "051_p_bank": "g_notice", "051_d_write": "g_notice", "051_p_gap": "g_use", "051_t_rec": "g_use"}},
  "a2b1-052": {"canDo": "Ma räägin, kumb pakkumine on parem: võrdlen hinda, suurust ja garantiid ning annan sõbrale põhjendatud nõu.", "goals": {"g_vocab": "Õpilane kasutab pakkumiste sõnu: pesumasin, pakkumine, võrra, vaikne, lai, kitsas, elekter, ladu, kohaletoomine, mõlemad.", "g_read": "Õpilane saab aru telefonikõnest poodi, kus müüja võrdleb kahte pesumasinat: hind, suurus, müra, garantii ja kohaletoomine.", "g_notice": "Õpilane võrdleb kahel viisil (odavam kui Vahu = Vahust odavam), ütleb vahe (70 euro võrra, palju vaiksem) ja kasutab ei ole nii … kui, mõlemad, kumbki.", "g_use": "Õpilane annab pildi „Kaks pesumasinat” järgi sõbrale põhjendatud nõu; kodus võrdleb päris hindu Hinnavaatlus.ee lehel."}, "tags": {"052_d_which": "g_vocab", "052_t_exit": "g_vocab", "052_p_call": "g_read", "052_d_retell": "g_read", "052_p_more": "g_notice", "052_p_sent": "g_notice", "052_t_advice": "g_use", "052_t_rec": "g_use"}},
  "a2b1-053": {"canDo": "Ma kirjutan e-poele 60–90-sõnalise kaebuse: mida ja millal tellisin, mis on valesti ja mida soovin (tellitud jope, makstud raha).", "goals": {"g_vocab": "Õpilane kasutab tagastamise sõnu: tellima, tellimus, pakk, pakend, kandma, täitma, tagastama, vahetama, katki, kehtiv.", "g_read": "Õpilane saab aru e-poe tagastamise tingimustest: tähtaeg, tagastamise vorm, kes maksab saatmise eest, millal tuleb raha tagasi.", "g_notice": "Õpilane kasutab kesksõna nimisõna ees: tellitud jope, makstud raha, avatud pakend, täidetud vorm, saadetud pakk (-tud ei muutu) ja kehtiv garantii (-v muutub).", "g_use": "Õpilane kirjutab pildi „Tellimus ja pakk” või oma ostu järgi e-poele 60–90-sõnalise kaebuse ilma antud alguseta (Harno B1 kirjutamine 2b nurk)."}, "tags": {"053_d_anna": "g_vocab", "053_t_exit": "g_vocab", "053_p_terms": "g_read", "053_d_retell": "g_read", "053_p_part": "g_notice", "053_p_sent": "g_notice", "053_t_mail": "g_use", "053_t_rec": "g_use"}},
  "a2b1-054": {"canDo": "Ma helistan töökotta või poodi, selgitan viisakalt, aga kindlalt probleemi ja lepin kokku lahenduse (parandage, saatke, vastake).", "goals": {"g_vocab": "Õpilane kasutab teenuse ja kaebuse sõnu: töökoda, remont, remondiakt, juhataja, nõudma, tõend, niiskus, rahulik, lahendus, arvustus.", "g_read": "Õpilane saab aru raadio tarbijanõustaja nõuannetest: kuidas kaevata rahulikult, faktidega ja selge sooviga, mida küsida töökojalt ja kuhu pöörduda; loeb töökoja kliendiküsitlust ja vastab sellele tervete lausetega.", "g_notice": "Õpilane kasutab viisakat, aga kindlat teie-käsku (rääkige, öelge, saatke, parandage, ärge võtke) ja kesksõna kaebuses (parandatud telefon).", "g_use": "Õpilane helistab pildi „Remondileht” järgi töökoja juhatajale, räägib faktidest, küsib tõendit ja lepib kokku lahenduse; teises ringis räägib oma teenuseprobleemist."}, "tags": {"054_d_survey": "g_vocab", "054_t_exit": "g_vocab", "054_p_radio": "g_read", "054_p_form": "g_read", "054_p_polite": "g_notice", "054_p_sent": "g_notice", "054_t_call": "g_use", "054_t_rec": "g_use"}},
  "a2b1-055": {"canDo": "Ma saan aru lühikestest teadetest ja raadioloost, räägin ilma abita ühest ostust, vahetan poes kingituse ja kirjutan sõbrale nõuande.", "goals": {"g_read": "Õpilane saab aru lühikestest teadetest poes ja raadioloost kasutatud asjade ostmisest; eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: -na ja protsendid poes, võrdlus (-st odavam, … võrra), kesksõna, viisakas teie-käsk.", "g_use": "Õpilane räägib ilma abita ühest ostust, vahetab poes kingituse ja kirjutab sõbrale 60–80-sõnalise nõuande; võrdleb tulemust tunni 51 külma stardiga."}, "tags": {"055_p_l1": "g_read", "055_p_l2": "g_read", "055_t_s1": "g_use", "055_t_call": "g_use", "055_t_w1": "g_notice"}},
  "a2b1-056": {"canDo": "Ma saan aru ilmateatest, räägin, kuidas ilm muutub, ja lepin sõbraga kokku, millal matkale minna.", "goals": {"g_vocab": "Õpilane kasutab ilma sõnu: ilmateade, äike, tuul, kraad, pilvine, jahe, hoiatus, muutuma.", "g_read": "Õpilane saab aru raadio nädalavahetuse ilmateatest (temperatuur, kellaajad, muutus, hoiatus) ja kirjutab paarilisega selle järgi plaani.", "g_notice": "Õpilane ütleb, kuidas ilm muutub: läheb jahedamaks, muutub tuuliseks, jääb soojaks, tõuseb kahekümne kraadini, oodatakse äikest.", "g_use": "Õpilane lepib pildi „Nädalavahetuse ilm” järgi sõbraga telefonis kokku matka päeva ja kellaaja, reageerib sõbra varjatud infole ja räägib päris ilmateate järgi oma homsest päevast."}, "tags": {"056_d_colleague": "g_vocab", "056_t_exit": "g_vocab", "056_d_radio": "g_read", "056_d_plan": "g_read", "056_p_cloze": "g_notice", "056_p_reply": "g_notice", "056_t_plan": "g_use", "056_t_real": "g_use", "056_t_home": "g_use"}},
  "a2b1-057": {"canDo": "Ma loen matkaloo, jutustan sündmused õiges järjekorras (kui, enne kui, pärast seda, kui) ja kirjutan matkagrupile postituse, mis juhtus ja mida ma sellest õppisin.", "goals": {"g_vocab": "Õpilane kasutab matka ja äikese sõnu: matk, laudtee, vaatetorn, raba, välk, müristama, tagasi pöörama, kiirustama, kukkuma, märg.", "g_read": "Õpilane loeb matkaja blogipostitust, leiab, mis juhtus enne ja mis pärast, ning jutustab paarilisega loo õiges järjekorras.", "g_notice": "Õpilane jutustab minevikus kui-, enne kui-, pärast seda, kui- ja samal ajal kui -lausetega, tegusõna kohe pärast kõrvallauset (Kui välk lõi, pöörasime me tagasi), ja kasutab vormi oli lubanud.", "g_use": "Õpilane kirjutab pildiloo „Äike rabas” või oma matka järgi matkagrupile 60–90-sõnalise postituse ilma antud alguseta ja vastab teise matkaja küsimustele."}, "tags": {"057_d_opinion": "g_vocab", "057_t_exit": "g_vocab", "057_d_bog": "g_read", "057_d_retell": "g_read", "057_d_order": "g_notice", "057_p_join": "g_notice", "057_p_sent": "g_notice", "057_p_plan": "g_use", "057_t_rec": "g_use", "057_t_blog": "g_use"}},
  "a2b1-058": {"canDo": "Ma saan aru tormiuudisest, seletan põhjust ja tagajärge ja helistan kindlustusse, kui osa kahjust jäi hüvitamata.", "goals": {"g_vocab": "Õpilane kasutab tormi ja kahju sõnu: torm, elekter, rike, kahju, kindlustus, hüvitama, põhjus, tagajärg.", "g_read": "Õpilane saab aru raadiouudisest öise tormi kohta (Harno kuulamine 2) ja kirjutab paarilisega uudise järgi põhjused ja tagajärjed.", "g_notice": "Õpilane seob põhjuse ja tagajärje: tugeva tuule tõttu, sest / kuna, seepärast + tegusõna kohe, nii et; parandab vead kirjas kindlustusele.", "g_use": "Õpilane helistab kahjuteate järgi kindlustusse, selgitab põhjuse ja tagajärjega, miks toit ja pump tuleb hüvitada, reageerib teenindaja varjatud infole ja jutustab oma tormiloo."}, "tags": {"058_d_ready": "g_vocab", "058_t_exit": "g_vocab", "058_d_radio": "g_read", "058_d_why": "g_read", "058_t_helgi": "g_notice", "058_t_call": "g_use", "058_t_own": "g_use", "058_t_home": "g_use", "058_p_forms": "g_notice"}},
  "a2b1-059": {"canDo": "Ma loen naabrite arvamusi, ütlen oma arvamuse koos põhjuse ja näitega (nõustun, loobume, osalen) ja lepin koosolekul kokku, mida meie hoovis 300 euroga teha.", "goals": {"g_vocab": "Õpilane kasutab kokkuleppe ja keskkonna sõnu: ettepanek, arvamus, kokkulepe, eelarve, keskkond, talgud, nõustuma, loobuma, osalema, hoolima.", "g_read": "Õpilane loeb maja foorumist kolme naabri ettepanekut ja kirjutab paarilisega iga naabri arvamuse, põhjuse ja näite.", "g_notice": "Õpilane ütleb arvamuse, põhjuse ja näite (Minu arvates …, sest … Näiteks …) ja kasutab õiget käänet: nõustuma millega, loobuma millest, osalema millel, hoolitsema mille eest.", "g_use": "Õpilane lepib koosolekul pildi „Kolm ettepanekut” järgi kokku ühe plaani, mis mahub 300 eurosse, reageerib naabri varjatud infole ja räägib oma maja ettepanekust nagu eksamil."}, "tags": {"059_d_board": "g_vocab", "059_t_exit": "g_vocab", "059_d_forum": "g_read", "059_d_find": "g_read", "059_d_ask": "g_read", "059_d_verbs": "g_notice", "059_p_sent": "g_notice", "059_t_meeting": "g_use", "059_t_rec": "g_use"}},
  "a2b1-060": {"canDo": "Ma loen artiklit rabast, saan aru raadioloost, räägin ilma abita, kuidas ilm minu plaane muutis, broneerin telefonis puhkemaja ja kirjutan sõbrale nõuande.", "goals": {"g_read": "Õpilane loeb populaarteadusliku artikli rabast ja saab aru raadioloost puukidest (õige või vale); eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab rääkides ja kirjutades mooduli vorme: läheb …-ks, kraadini, oodatakse; kui- ja enne kui -laused õige sõnajärjega; tõttu, seepärast, nii et.", "g_use": "Õpilane räägib ilma abita, kuidas ilm tema plaane muutis, broneerib telefonis puhkemaja ootamatu vastusega ja kirjutab sõbrale 60–90-sõnalise nõuande; võrdleb tulemust tunni 56 külma stardiga."}, "tags": {"060_p_r2text": "g_read", "060_p_l2": "g_read", "060_t_s1": "g_use", "060_t_s2": "g_use", "060_t_w": "g_notice"}},
  "a2b1-061": {"canDo": "Ma palun naabrilt või kolleegilt abi, teen ettepaneku, keeldun viisakalt ja lepin kokku, kes mida teeb.", "goals": {"g_vocab": "Õpilane kasutab palve ja keeldumise sõnu: paluma, soovitama, keelama, lubama, keelduma, nõus olema, valmis olema, ettepanek, vastu võtma, kokku leppima.", "g_read": "Õpilane loeb lehe nõuandeveergu (lugeja kiri ja nõustaja vastus), leiab, kuidas paluda ja keelduda, ning leiab maja infotahvlilt igale inimesele sobiva kuulutuse (Harno R1).", "g_notice": "Õpilane annab palve edasi (palub mul aidata, soovitab mulle puhata, keelab panna, lubab minna), kasutab nõus / valmis olema + ma ja keeldub viisakalt: kahjuks + põhjus + uus pakkumine.", "g_use": "Õpilane lepib pildi „Kolimispäev” järgi naabriga ukse taga kokku, millega see aitab, reageerib keeldumisele uue ettepanekuga ja palub ilma fraasideta abi oma päris olukorras."}, "tags": {"061_d_meet": "g_vocab", "061_t_exit": "g_vocab", "061_d_letter": "g_read", "061_d_find": "g_read", "061_d_ask": "g_read", "061_p_ads": "g_read", "061_p_pass": "g_notice", "061_d_write": "g_notice", "061_t_agree": "g_use", "061_t_rec": "g_use"}},
  "a2b1-062": {"canDo": "Ma saan aru raadiosaatest viisakast suhtlemisest ja helistan teenindusse: palun ja küsin tingiva kõneviisiga ning lahendan probleemi.", "goals": {"g_vocab": "Õpilane kasutab teeninduse sõnu: viisakas, järsk, teenindus, broneering, vastuvõtt, administraator, kaebus, vabandama, võimalik, lahendus.", "g_read": "Õpilane saab aru raadiosaatest viisakatest palvetest (Harno B1 kuulamine 2: kolme vastusega küsimused) ja jutustab paarilisega, miks viisakas palve aitas.", "g_notice": "Õpilane palub ja küsib tingiva kõneviisiga: Kas te saaksite …? Ma sooviksin … Kas oleks võimalik saada …? Mida te soovitaksite? ja moodustab vormid (saaksin, oleks, teeksin, läheksin).", "g_use": "Õpilane helistab pildi „Broneeringu kinnitus” järgi hotelli vastuvõttu, reageerib administraatori varjatud infole, leiab lahenduse ja valmistab ilma fraasideta ette päris kõne eesti keele vestlusringi korraldajale."}, "tags": {"062_d_photo": "g_vocab", "062_t_exit": "g_vocab", "062_d_port": "g_read", "062_d_rule": "g_read", "062_d_retell": "g_read", "062_p_polite": "g_notice", "062_p_would": "g_notice", "062_p_sent": "g_notice", "062_t_call": "g_use", "062_t_rec": "g_use", "062_t_home": "g_use"}},
  "a2b1-063": {"canDo": "Ma saan aru, mida räägitakse, annan kuuldud juttu edasi kaudse kõneviisiga (olevat, tulevat, olevat teinud) ja kirjutan loo, kuidas kuulujutt sündis ja mis oli tegelikult.", "goals": {"g_vocab": "Õpilane kasutab kuulujutu sõnu: kuulujutt, väidetavalt, tegelikult, … sõnul, levima, selguma, uskuma, kinnitama, edasi saatma.", "g_read": "Õpilane loeb linnaosa lehe artiklit kuulujutust, eristab kuulujuttu ja tegelikkust ning ütleb oma arvamuse, miks kuulujutud levivad.", "g_notice": "Õpilane annab kuuldut edasi kaudse kõneviisiga (olevat, tulevat, olevat müünud, ei olevat), kasutab … sõnul ja väidetavalt, ütleb fakti kindla kõneviisiga (tegelikult …) ja paneb raamatukogu teatesse puuduvad lauseosad (Harno R4).", "g_use": "Õpilane kirjutab pildi „Maja vestlus” või oma loo järgi 70–100-sõnalise loo „Kuidas kuulujutt sündis” ilma antud alguseta ja jutustab selle paarilisele ilma tekstita."}, "tags": {"063_d_rumour": "g_vocab", "063_t_exit": "g_vocab", "063_d_chat": "g_read", "063_d_rule": "g_read", "063_d_432": "g_notice", "063_t_notice": "g_notice", "063_d_opinion": "g_read", "063_p_sent": "g_notice", "063_t_tale": "g_use", "063_t_rec": "g_use"}},
  "a2b1-064": {"canDo": "Ma saan aru töökoosolekust, kus inimesed on eri arvamusel, kirjutan kokkuleppe kohta juhatajale kirja ja lepin kolleegidega ise kokku.", "goals": {"g_vocab": "Õpilane kasutab koosoleku sõnu: koosolek, arvamus, kompromiss, kokkulepe, segama, keskenduma, kõrvaklapid, vaikus, proovima, kokkuvõte.", "g_read": "Õpilane saab aru töökoosolekust (neli arvamust ja kompromiss), kirjutab paarilisega üles, kes mida arvas, ning vastab töökoha küsitlusele tervete lausetega (Harno W1a).", "g_notice": "Õpilane annab arvamusi ja kokkulepet kirjas edasi (Kerli sõnul, Rasmuse arvates, leppisime kokku, et, kuigi, seega, Kas me saaksime …?).", "g_use": "Õpilane kirjutab pildi „Koosoleku märkmed” järgi juhatajale 80–100-sõnalise kirja ilma antud alguseta (Harno W2b), lepib kolleegiga varjatud infoga kokku köögi korra (Harno S1b) ja räägib kokkuleppe häälsõnumisse."}, "tags": {"064_d_opinion": "g_vocab", "064_t_exit": "g_vocab", "064_p_liis": "g_read", "064_d_views": "g_read", "064_d_survey": "g_read", "064_p_form": "g_read", "064_p_join": "g_notice", "064_t_plan": "g_notice", "064_t_mail": "g_use", "064_t_meeting": "g_use", "064_t_home": "g_use"}},
  "a2b1-065": {"canDo": "Ma loen kirja ja teadet, saan aru raadioloost, räägin ilma abita ühest raskest vestlusest ja lepin kolleegiga kokku.", "goals": {"g_read": "Õpilane täidab sõnapangaga kirja ja lauseosade pangaga teate lüngad ning saab aru raadioloost hotellikaebustest (kolme vastusega küsimused); eesmärk vähemalt 60 % punktidest.", "g_notice": "Õpilane kasutab mooduli vorme: paluma + da, nõus olema + ma, tingiv kõneviis viisakas palves, kaudne kõneviis (olevat), … sõnul, kuigi.", "g_use": "Õpilane räägib ilma abita ühest raskest vestlusest ja lepib kolleegiga kokku keelekohviku plaani; võrdleb tulemust tunni 61 külma stardiga."}, "tags": {"065_p_r3": "g_read", "065_p_r4": "g_read", "065_p_l2": "g_read", "065_t_s1": "g_use", "065_t_s1b": "g_use"}},
  "a2b1-066": {"canDo": "Ma kirjutan umbes 100-sõnalise loo sellest, kuidas midagi lõpuks valmis sai: mis juhtus, mis jäi pooleli ja mis sai lõpuni tehtud.", "goals": {"g_vocab": "Õpilane kasutab lõpetatuse ja kodu sõnu: valmis, ära, läbi, pooleli, lõpuni, katus, ahi, aken, värvima, meister, hakkama saama; kordab sõnu remont, tellima, kokkulepe.", "g_read": "Õpilane loeb lugejaloo „Maja, mis sai valmis ühe suvega”, ennustab pealkirja järgi ja kirjutab paarilisega, mis sai valmis ja mis jäi pooleli.", "g_notice": "Õpilane näitab lõpetatust: tegusõna + ära, läbi või valmis + täissihitis (parandasime katuse ära, lugesin juhendi läbi), eituses osastav (ei teinud remonti valmis); kuuleb väldet kapi – kappi.", "g_use": "Õpilane kirjutab ilma abita külma loo, kirjutab piltide järgi loo „Rõdu ühe nädalavahetusega” (Harno W2a) ja parandab väljumisel ühe oma lause."}, "tags": {"066_d_vocab": "g_vocab", "066_d_story": "g_read", "066_d_choice": "g_read", "066_d_find": "g_read", "066_p_done": "g_notice", "066_t_exit": "g_notice", "066_d_write": "g_vocab", "066_t_tale": "g_use", "066_t_rec": "g_use", "066_p_sent": "g_vocab"}},
  "a2b1-067": {"canDo": "Ma küsin ja räägin kogemustest täisminevikus, ütlen lihtminevikus, millal see oli, ja teen väikese küsitluse.", "goals": {"g_vocab": "Õpilane kasutab kogemuse sõnu: kogemus, kunagi, esimest korda, julge, kartma, langevari, hüppama, virmalised, talisuplus, sellest ajast; kordab sõnu proovima, soovitama, tegelikult.", "g_read": "Õpilane saab aru saatest „Esimest korda” (Harno B1 kuulamine 4: õige või vale) ja kirjutab paarilisega, mis on kogemus ja mis kindel aeg.", "g_notice": "Õpilane valib täismineviku kogemuse jaoks (olen hüpanud, ei ole kunagi näinud) ja lihtmineviku kindla aja jaoks (2022. aastal töötasin); hääldab õ, ä, ö, ü.", "g_use": "Õpilane kirjutab oma küsitluse, küsitleb paarilist, võtab tulemused kokku ja otsustab, mida koos proovida; kodus kuulab ERR Jupiterist päris saadet."}, "tags": {"067_d_gen": "g_vocab", "067_d_pod": "g_read", "067_d_rule": "g_read", "067_p_forms": "g_notice", "067_p_quest": "g_notice", "067_t_exit": "g_vocab", "067_t_survey": "g_use", "067_t_again": "g_use", "067_t_home": "g_use"}},
  "a2b1-068": {"canDo": "Ma jutustan ühe inimese elust ajajoone järgi, kasutan kolme minevikku ja võrdlen paarilisega kaht elu.", "goals": {"g_vocab": "Õpilane kasutab eluloo sõnu: sündima, kasvama, kolima, abielluma, lõpetama, pensionile jääma, õmblema, palk, selleks ajaks, hiljem; kordab sõnu töökoda, muutuma, selguma.", "g_read": "Õpilane loeb ühe kahest elulootekstist (Leida või Andrei), vastab neljale küsimusele ja teeb oma inimese ajajoone tervete lausetega.", "g_notice": "Õpilane valib liht-, täis- või enneminevikku (abiellus, on elanud, oli töötanud) ja paneb pärast aega tegusõna teisele kohale (2015. aastal kolis ta); Harno B1 lugemine 3b sõnapangaga.", "g_use": "Õpilane jutustab oma inimese elust ilma tekstita, küsib paariliselt varjatud infot, täidab ühise ajajoone ja leiab kolm sarnasust."}, "tags": {"068_d_photo": "g_vocab", "068_d_lives": "g_read", "068_d_line": "g_read", "068_p_letter": "g_notice", "068_p_sent": "g_notice", "068_t_exit": "g_vocab", "068_t_poster": "g_use", "068_t_rec": "g_use"}},
  "a2b1-069": {"canDo": "Ma jutustan 2–3 minutit ühest päevast neljas osas, seon loo sidesõnadega ja vastan kuulajate küsimustele.", "goals": {"g_vocab": "Õpilane kasutab loo sõnu: eksima, hirmus, äkki, kõigepealt, lõpuks, kuigi, koputama, ööbima, järeldus, publik, unustama; kordab sõnu kraad, kiirustama, vabandama.", "g_read": "Õpilane saab aru lugude õhtu loost (Harno B1 kuulamine 3a: 1–2 sõna), kirjutab loo neli osa ja jutustab Maria loo paarilisele.", "g_notice": "Õpilane valib sidesõna (kõigepealt, siis, äkki, sest, seepärast, kuigi, lõpuks) ja paneb tegusõna pärast seda teisele kohale; teeb loos õiged pausid.", "g_use": "Õpilane jutustab lugude õhtul oma loo fotoga, vastab kahele küsimusele, annab paarilisele kaks tähte ja ühe soovi ning kirjutab loo kodus."}, "tags": {"069_d_opinion": "g_vocab", "069_d_tale": "g_read", "069_d_rule": "g_read", "069_d_retell": "g_read", "069_p_links": "g_notice", "069_p_plan": "g_notice", "069_t_exit": "g_vocab", "069_t_talk": "g_use", "069_t_rec": "g_use"}},
  "a2b1-070": {"canDo": "Ma loen elulugu ja kirja, selgitan naabrile lihtsalt üht teadet ja kirjutan ilma abita loo ühest oma päevast.", "goals": {"g_read": "Õpilane saab aru eluloost (lühivastused) ja täidab sõnapangaga kirja lüngad (Harno R3b); eesmärk vähemalt 60 % lugemise punktidest.", "g_notice": "Õpilane kasutab mooduli vorme: ära, läbi, valmis + täissihitis, täisminevik kogemuse jaoks, enneminevik, ning mooduli 13 vorme olevat, paluma + da ja tingiv kõneviis.", "g_use": "Õpilane selgitab naabrile muuseumi teadet (vahendus, W1) ja kirjutab ilma abita 80–100 sõna loo (W2), mida võrreldakse tunni 66 külma loo tulemusega."}, "tags": {"070_p_r2text": "g_read", "070_p_r3": "g_notice", "070_t_w1": "g_use", "070_t_w2": "g_use"}},
  "a2b1-071": {"canDo": "Ma räägin oma plaanidest järgmiseks aastaks ja helistan kursusele, et küsida infot ja kokku leppida, millal ma alustan.", "goals": {"g_vocab": "Õpilane kasutab tuleviku ja kursuste sõnu: tulevik, eesmärk, kavatsema, hakkama, tähtaeg, registreeruma, soodustus, algaja, vaba koht, ootejärjekord; kordab sõnu kogemus, võimalik, soovitama.", "g_read": "Õpilane saab aru raadiosaatest uue aasta võimalustest (Harno B1 kuulamine 2: valikvastused) ja kirjutab paarilisega, mis millal juhtub; kodus loeb Harno päris lehte.", "g_notice": "Õpilane räägib tulevikust ilma tulevikuvormita: aeg + olevik (jaanuaris algab), hakkama + ma (hakkan käima), kavatsema + da (kavatsen teha), muutuma + -ks, tähtaeg -ks (reedeks); täidab kirja lauseosade pangaga.", "g_use": "Õpilane räägib ilma abita oma plaanist (külm ülesanne), helistab kuulutuse järgi kursusele ja lepib kokku koha, helistab plaani muutudes tagasi ja jätab 30-sekundilise häälsõnumi."}, "tags": {"071_d_cold": "g_vocab", "071_p_sent": "g_vocab", "071_d_radio": "g_read", "071_d_plan": "g_read", "071_t_home": "g_read", "071_p_letter": "g_notice", "071_t_exit": "g_notice", "071_t_call": "g_use", "071_t_again": "g_use"}},
  "a2b1-072": {"canDo": "Ma loen reegleid, kus on möönev kõneviis, ja kirjutan naabrile lihtsalt, mida need tähendavad: peab, võib, ei tohi, ei pea, las.", "goals": {"g_vocab": "Õpilane kasutab aia ja reeglite sõnu: reegel, kord, hooaeg, peenar, tööriist, kastma, umbrohi, prügi, osaleja, las, olgu peale, lihtsalt; kordab sõnu keelama, lubama, segama.", "g_read": "Õpilane loeb kogukonnaaia korda (≈ 210 sõna), vastab kaheksale küsimusele 1–4 sõnaga ja kirjutab paarilisega, mis on kohustus, luba või keeld.", "g_notice": "Õpilane tunneb ära mööneva kõneviisi (hoolitsegu, pangu, ärgu segagu) ja ütleb sama lihtsalt: peab + ma, tuleb + da, võib, ei tohi, ei pea, las + olevik (las ta jääb); täidab kirja sõnapangaga (Harno R3b).", "g_use": "Õpilane kirjutab uuele naabrile 60–80-sõnalise sõnumi, mis selgitab aia korda lihtsate vormidega (vahendus), parandab ühe oma lause ja vastab kodus suuliselt naabri kahele uuele küsimusele."}, "tags": {"072_d_warm": "g_vocab", "072_t_exit": "g_vocab", "072_d_story": "g_read", "072_d_find": "g_read", "072_p_plain": "g_notice", "072_p_sent": "g_notice", "072_t_med": "g_use", "072_t_home": "g_use"}},
  "a2b1-073": {"canDo": "Ma saan aru raadiojutust, kuidas plaani B teha, ja lepin paarilisega kokku plaani A ja plaani B kui-lausetega.", "goals": {"g_vocab": "Õpilane kasutab tingimuse ja väljasõidu sõnu: tingimus, juhul kui, väljasõit, õnnestuma, ära jääma, võimalus, ette mõtlema, vihmane, rada, eelarve; kordab sõnu kompromiss, tagajärg, ettepanek.", "g_read": "Õpilane saab aru raadiosaatest „Plaan B” (Harno B1 kuulamine 2: valikvastused) ja kirjutab paarilisega viis kui-lauset, mis juhtub ja mida siis teha.", "g_notice": "Õpilane teeb kui-lauseid: päris võimalus kui + olevik ja tegusõna kohe pärast kui-lauset (Kui sajab, läheme …), unistus tingiva kõneviisiga mõlemas osas (Kui oleks aega, sõidaksime …), juhul kui; täidab teate lauseosade pangaga.", "g_use": "Õpilane lepib paarilisega kokku naabrite laupäeva plaani A ja plaani B ideekaardi ja varjatud info järgi, võtab plaani 30 sekundiga kokku ja räägib kodus ühest eestikeelsest saatest."}, "tags": {"073_d_warm": "g_vocab", "073_t_exit": "g_vocab", "073_d_radio": "g_read", "073_d_rule": "g_read", "073_p_join": "g_notice", "073_p_sent": "g_notice", "073_t_decide": "g_use", "073_t_home": "g_use"}},
  "a2b1-074": {"canDo": "Ma kirjutan oma tegevusplaani 80–100 sõnaga ja lepin paarilisega kokku kolm esimest sammu.", "goals": {"g_vocab": "Õpilane kasutab plaani sõnu: tegevusplaan, samm, takistus, harjumus, mõõtma, edu, alates, kuni, hiljemalt, järjest, raskus, toetaja; kordab sõnu keskenduma, järeldus, kokkuvõte.", "g_read": "Õpilane täidab programmi küsimustiku ja saab aru seitsmest häälsõnumist, kus osalejad räägivad oma plaanist (Harno B1 kuulamine 1): kelle plaanis on aeg, plaan B ja toetaja.", "g_notice": "Õpilane kasutab plaani keelt: alates jaanuarist, kuni juunini, hiljemalt märtsiks, igal teisipäeval, selleks, et …, kui … ei õnnestu, siis …; täidab ühe õppija plaani lauseosade pangaga.", "g_use": "Õpilane kirjutab mustandi ja malli järgi oma tegevusplaani, lepib mentoriga kokku kolm esimest sammu, parandab esimese sammu ja saadab plaani kaaslasele."}, "tags": {"074_p_draft": "g_vocab", "074_t_meet": "g_vocab", "074_d_clips": "g_read", "074_d_apply": "g_read", "074_p_text": "g_notice", "074_t_exit": "g_notice", "074_t_plan": "g_use", "074_t_home": "g_use"}},
  "a2b1-075": {"canDo": "Ma saan aru lühikestest teadetest ja raadiojutust plaanide kohta, räägin ilma abita oma plaanist ja lepin kaaslasega kokku plaani A ja plaani B.", "goals": {"g_read": "Õpilane saab aru kaheksast lühikesest teatest (Harno L1) ja raadiojutust uue aasta lubadustest (Harno L2); eesmärk vähemalt 60 % kuulamise punktidest.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed teated” ja „Raadiolugu” (valikvastused, kumbki kõlab kaks korda).", "g_notice": "Õpilane kasutab mooduli vorme: tulevik aja ja olevikuga, hakkama + ma, kavatsema + da, tähtaeg -ks, kui-lause sõnajärg ja tingiv kõneviis unistuse jaoks; tunneb ära mooduli 13–14 vormid (olevat, ei ole kunagi proovinud).", "g_use": "Õpilane räägib ilma abita oma uuest oskusest ja plaanist (tunni 71 külma ülesande paralleel: kuus eksamineerija küsimust) ja lepib kaaslasega kokku lõpupeo plaani A ja plaani B."}, "tags": {"075_p_l1": "g_listen", "075_p_l2": "g_listen", "075_t_s1": "g_use", "075_t_s1b": "g_use"}},
  "a2b1-076": {"canDo": "Ma räägin oma arvamusest laste telefonide ja ekraaniaja kohta, põhjendan seda ja lepin lastevanemate koosolekul kokku klassi ühise seisukoha.", "goals": {"g_vocab": "Õpilane kasutab arvamuse ja tehnoloogia sõnu: arvamus, minu arvates, arvama, tunduma, kindel, kahtlema, nõustuma, nutitelefon, ekraan, reegel, keelama, vanus; valib arvamuse väljendi selle järgi, kui kindel ta on.", "g_read": "Õpilane saab kuuldust aru Metsade õhtusöögi vaidlusest, raadio tänavaküsitlusest ja klassijuhataja häälsõnumist ning loeb lastevanemate foorumit.", "g_listen": "Õpilane saab aru kuulamistekstidest „Õhtusöök Metsade köögis” ja „Tänavaküsitlus raadios” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ütleb arvamuse kindluse järgi (olen kindel, ma arvan, mulle tundub, ma kahtlen), paneb pärast „minu arvates” ja ees olevat kuna-lauset tegusõna kohe ning põhjendab sõnadega sest ja kuna.", "g_use": "Õpilane küsitleb kolme inimest, ütleb oma arvamuse kolm korda, vastab teemaküsimustele, lepib lastevanemate koosolekul kokku klassi seisukoha, salvestab oma arvamuse ja vastab klassijuhatajale."}, "tags": {"076_d_kitchen": "g_listen", "076_p_poll": "g_listen"}},
  "a2b1-077": {"canDo": "Ma loen artiklit ja kolleegide arvamusi kaugtöö kohta, võrdlen kolme võimalust ja kirjutan juhatajale 90–110-sõnalise ettepaneku.", "goals": {"g_vocab": "Õpilane kasutab võrdlemise ja töö sõnu: võrdlema, võrreldes, kaugtöö, kontor, eelis, puudus, mugav, rahulik, säästma, eelistama, kolleeg, vaikne; ühendab väljendid õige käändega ja leiab kuulutustest sobiva töökoha.", "g_read": "Õpilane loeb firma infolehe artiklit kaugtöö küsitlusest ja kolme variandi kirjeldust ning saab kuuldust aru kolleegide häälsõnumitest ja raadiosaatest e-riigist.", "g_listen": "Õpilane saab aru kuulamistekstidest „Kolleegide häälsõnumid” ja „Raadio: kaugtöö ja e-riik” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane võrdleb keskvõrde ja sõnaga kui, ülivõrdega (kõige …), väljenditega sama … kui, võrreldes + -ga ja erinevalt + -st ning parandab võrdluse vead (nagu → kui, paremam → parem).", "g_use": "Õpilane võrdleb kahte töökohta kolm korda, kirjutab kaheksa minutit oma tööpäevast, vahetab infot kahe variandi kohta, paneb tiimiga variandid järjekorda, salvestab oma võrdluse ja kirjutab Liisile ettepaneku."}, "tags": {"077_d_voices": "g_listen", "077_p_radio": "g_listen"}},
  "a2b1-078": {"canDo": "Ma saan kuuldust aru argumentidest linna ja hoovi teemal ning kirjutan maja infolehele arvamusloo, kus on kaks argumenti põhjuse, näite ja järeldusega.", "goals": {"g_vocab": "Õpilane kasutab argumendi ja linnaelu sõnu: põhjendama, näiteks, järeldus, seepärast, seega, hoov, mänguväljak, ohutu, liiklus, kiirus, hääletama, linnaosa; valib sidesõna põhjuse, tagajärje, näite või vastanduse jaoks.", "g_read": "Õpilane saab kuuldust aru linnaosa uudisest kaasava eelarve kohta ja raadiointervjuust kiiruse kohta ning loeb kuulajate kommentaare ja Urmase artiklit maja infolehes.", "g_listen": "Õpilane saab aru kuulamistekstidest „Linnaosa uudised” ja „Intervjuu kiirusest” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ehitab argumendi arvamus → põhjus → näide → järeldus, paneb pärast seepärast, seega ja näiteks tegusõna kohe ning täpsustab kes- ja mis-lausega (kellel, millest, mida).", "g_use": "Õpilane jutustab uudise kaks korda ümber, seletab naabrile linnaosa plaani, kirjutab Karli postituse viisakaks, helistab linnaosa valitsusse, salvestab oma raadiokommentaari ja kirjutab ning toimetab arvamusloo."}, "tags": {"078_d_news": "g_listen", "078_p_siret": "g_listen"}},
  "a2b1-079": {"canDo": "Ma loen naabrite ettepanekuid, arutan elanike koosolekul viisakalt hoovi tulevikku ja lepin teistega kokku kompromissi.", "goals": {"g_vocab": "Õpilane kasutab arutelu sõnu: arutelu, ettepanek, kompromiss, kokkulepe, koosolek, otsus, poolt, vastu, eelarve, seisukoht, viisakas, vaidlema; leiab teravale lausele viisaka vastuse ja tõlgib viisakad laused.", "g_read": "Õpilane loeb ühistu esimehe kirja, kutset koosolekule ja ettepanekute lehte koos hindadega ning saab kuuldust aru esimehe häälsõnumist enne koosolekut.", "g_listen": "Õpilane saab aru kuulamistekstidest „Raadio: kuidas naabritega kokku leppida?” ja „Urmase häälsõnum enne koosolekut” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane ütleb arvamuse viisakalt tingivas kõneviisis (ma arvaksin, oleks parem, me võiksime, kas te oleksite nõus), nõustub osaliselt ja esitab vastuküsimuse (Aga mis saab siis, kui…?).", "g_use": "Õpilane proovib naabriga probleemi kaks korda lahendada, täidab maja küsitluse, vastab küsimustele „Mida sa teeksid?”, lepib koosolekul kokku kompromissi, salvestab koosoleku kokkuvõtte ja kirjutab otsuse maja jutugruppi."}, "tags": {"079_d_radio": "g_listen", "079_p_voice": "g_listen"}},
  "a2b1-080": {"canDo": "Ma sooritan teise täispika proovieksami Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin; vahekontrolli lävi on 75 % ja eesmärk 80 % igas osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu arvamuse, võrdlemise ja põhjendamise kohta: arvamus, minu arvates, kahtlema, reegel, võrdlema, eelis, puudus, kaugtöö, järeldus, seepärast, kompromiss, ettepanek.", "g_read": "Õpilane saab lugemises (33 punkti) vähemalt 25 ja kuulamises (30 punkti) vähemalt 23 punkti; eesmärk on 80 % (27 ja 24 punkti).", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli vorme: tegusõna kohe pärast „minu arvates”, kuna-lauset, seepärast ja seega; keskvõrre + kui, kõige, võrreldes + -ga; kes- ja mis-laused; viisakas tingiv kõneviis.", "g_use": "Õpilane saab kirjutamises ja rääkimises (kumbki 20 punkti) vähemalt 15 punkti; eesmärk on 16 punkti; alla läve jäänud osa vaatab õpetaja enne moodulit 17 õpilasega läbi."}, "tags": {"080_p_l1": "g_listen", "080_p_l2": "g_listen", "080_p_l3": "g_listen", "080_p_l4": "g_listen"}},
  "a2b1-081": {"canDo": "Ma loen maja ja tänava teateid, seletan neid uuele naabrile ning helistan värvifirmasse ja küsin umbisikulise vormiga, millal ja kuidas töid tehakse.", "goals": {"g_vocab": "Õpilane kasutab maja ja teadete sõnu: teade, trepikoda, elanik, naaber, kelder, toru, ahi, remont, värvima, koristama, keelatud, palve; leiab kuulutustest majale sobiva teenuse.", "g_read": "Õpilane loeb lugu Ruslani esimesest nädalast ja maja teadetest ning saab kuuldust aru linnaosa raadiouudistest ja Tiina häälsõnumist.", "g_notice": "Õpilane moodustab umbisikulise tegumoe olevikus, minevikus ja eituses (vahetatakse, värviti, ei köeta) ja paneb täissihitise umbisikulises lauses nimetavasse (torud vahetatakse).", "g_use": "Õpilane seletab teateid uuele naabrile, kirjutab kaheksa minutit oma ümbruse teadetest, vastab teemaküsimustele, helistab värvifirmasse, salvestab oma maja teadete seletuse ja vastab Tiinale."}},
  "a2b1-082": {"canDo": "Ma loen ametlikku kirja ja juhendit asutusele kirjutamise kohta, võrdlen kolme võimalust asutusega suhelda ja kirjutan linnaosa valitsusele 90–110-sõnalise ametliku kirja.", "goals": {"g_vocab": "Õpilane kasutab asjaajamise sõnu: asutus, taotlus, avaldus, vastus, otsus, lisa, selgitus, pöörduma, esitama, allkirjastama, tutvuma, menetlema; jagab ametliku kirja lugemise nõuanded enne, ajal ja pärast lugemist.", "g_read": "Õpilane loeb juhendit asutusele kirjutamise kohta ja linnaosa valitsuse vastust, saab kuuldust aru e-teenuses taotluse esitamise sammudest, täidab Sofia kirja lauseosadega ja võrdleb kolme võimalust asutusega suhelda.", "g_notice": "Õpilane kasutab tegusõnu õige käändega (pöörduma asutuse poole, vastama kirjale, aru saama kirjast, tutvuma dokumendiga, sõltuma otsusest) ja moodustab tegusõnast nimisõna (taotlus, taotleja, otsus, vastus).", "g_use": "Õpilane küsitleb paarilist asjaajamise kohta, jutustab oma asjaajamise loo, vahetab infot kahe taotluse kohta, lepib kokku, kuidas asutusega suhelda, lahendab linnaosa vastuvõtul probleemi, ütleb sõnavõtus arvamuse e-teenuste kohta ja kirjutab linnaosa valitsusele kirja."}},
  "a2b1-083": {"canDo": "Ma saan raadiosaatest ja telefonikõnest aru, kuidas keeleeksamile registreerida ja riigi e-teenust turvaliselt kasutada, annan kuuldu edasi ning koostan ja tutvustan koos naabritega uue elaniku meelespea.", "goals": {"g_vocab": "Õpilane kasutab eksami ja asjaajamise sõnu: eksam, registreerima, tähtaeg, dokument, isikukood, sõnaraamat, hilinema, tunnistus, osa, ruum, kinnitama, kaasa; täidab sõnumid sobivate sõnadega.", "g_read": "Õpilane saab kuuldust aru raadiosaatest eksamist, Ruslani kõnest Sotsiaalkindlustusametisse ja Tiina jutust majakoosolekul ning loeb turvalise asjaajamise meelespead.", "g_listen": "Õpilane saab aru kuulamistekstidest Raadio „Päevateema”: eksamiks valmis?, „Ruslan helistab Sotsiaalkindlustusametisse” ja „Tiina koosolekul: mida uus elanik peab tegema?” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane annab kuuldut edasi: umbisikuline minevik (öeldi, soovitati), et- ja kas-lause, isiku muutus (ma → ta), soovitas + da-tegevusnimi ja kellegi sõnul.", "g_use": "Õpilane räägib saatest kolm korda, vastab „Mida sa teeksid?” küsimustele ja eksamineerija küsimustele avalike teenuste kohta, täidab linnaosa küsimustiku, paneb koos naabriga meelespea punktid järjekorda ja tutvustab meelespead naabritele."}, "tags": {"083_d_radio": "g_listen", "083_p_ska": "g_listen", "083_t_meeting": "g_listen"}},
  "a2b1-084": {"canDo": "Ma kirjutan majale 50-sõnalise teate talgutest ja sõbrale 90–110-sõnalise kirja ning toimetan oma kirja rubriigi järgi.", "goals": {"g_vocab": "Õpilane kasutab kirja ja teate sõnu: kiri, sõnum, tervitus, sisu, lause, parandama, viisakas, talgud, kutsuma, kirjeldama, teema, osalema; eristab teate, sõbrakirja ja ametliku kirja väljendeid ning kordab mooduli sõnu ristsõnas.", "g_read": "Õpilane saab kuuldust aru raadiointervjuust ja kümnest lühikesest teatest, loeb Lena kirja, Sofia mustandit ja talgute küsitluse tulemusi ning leiab iga lõigu ülesande.", "g_listen": "Õpilane saab aru kuulamistekstidest „Raadio: kuidas kirjutada head teadet ja kirja?” ja „Kümme lühikest teadet” (küsimused kuuldu kohta).", "g_notice": "Õpilane ehitab teate ja kirja (pöördumine, lõigud, lõpp), ühendab laused sidesõnadega (kõigepealt, seejärel, peale selle, lõpuks, seepärast), valib sina- või teie-vormi ja parandab mustandi vead.", "g_use": "Õpilane võrdleb kodu talvel ja kevadel, ütleb arvamuse paberi ja ekraani kohta, kirjutab Ruslani sõnumi viisakaks, lepib Tiinaga kokku teate sisu, salvestab suulise kutse naabritele, kirjutab teate majale ja kirja Lenale ning toimetab selle."}, "tags": {"084_d_radio": "g_listen", "084_p_clips": "g_listen"}},
  "a2b1-085": {"canDo": "Ma lahendan Harno B1 lugemise ja kirjutamise osa ajapiiranguga: neli lugemisülesannet 50 minutiga ning küsimustiku ja isikliku kirja 35 minutiga; eesmärk on vähemalt 80 % kummaski osas.", "goals": {"g_vocab": "Õpilane tunneb mooduli sõnu teadete, eksami, kirjade ja õppimise kohta: teade, elanik, remont, tulemus, eesmärk, valmistuma, tähtaeg, dokument, kiri, tervitus, talgud, viisakas.", "g_read": "Õpilane lahendab Harno B1 lugemise neli ülesannet (olukord ↔ kuulutus, artikkel valikvastustega, sõnapangaga lünktekst, lauseosade pank) ajapiiranguga ja saab vähemalt 27 punkti 33-st.", "g_notice": "Õpilane kasutab õigesti mooduli vorme: umbisikuline tegumood, kuuldu edasiandmine (öeldi, ta ütles, et…), tegusõnade rektsioon ja sidesõnad koos õige sõnajärjega.", "g_use": "Õpilane täidab küsimustiku ja kirjutab sõbrale 100-sõnalise isikliku kirja ajapiiranguga, saab kirjutamises vähemalt 16 punkti 20-st ning parandab oma kirja rubriigi järgi."}},
  "a2b1-086": {"canDo": "Ma saan häälsõnumist ja raadiointervjuust aru, mis muutus, helistan keelekooli, selgitan viisakalt oma probleemi ja lepin kokku uue lahenduse.", "goals": {"g_vocab": "Õpilane kasutab muudatuse ja probleemi sõnu: muudatus, tühistama, asendama, pakkuma, lahendus, kaebus, vabandama, võimalus, kokkulepe, eksamineerija, partner, salvestama; sorteerib kõne laused ja ühendab tegusõna sobiva jätkuga.", "g_read": "Õpilane saab kuuldust aru keelekooli ja Olena häälsõnumist ning raadiointervjuust suulise eksami kohta (Harno B1 kuulamine 4) ja loeb keelekooli tingimusi.", "g_listen": "Õpilane saab aru kuulamistekstidest „Krista häälsõnum: mis muutus?” ja „Kuidas käib suuline eksam?” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane räägib probleemist viisakalt: kahjuks ei sobi…, kas oleks võimalik…, ma sooviksin…, kas te saaksite…; kasutab umbisikulist minevikku (jäeti ära, pakuti) ja kontrollib kuuldut (kas ma saan õigesti aru, et…).", "g_use": "Õpilane proovib kõnet keelekooli kaks korda, jutustab katki läinud plaanist, kirjutab pahase sõnumi viisakaks, avaldab arvamust pühade, töö ja plaanide kohta, helistab Kristale ja lepib kokku lahenduse, salvestab loo lahendatud probleemist ja kinnitab kokkuleppe kirjalikult."}, "tags": {"086_d_voice": "g_listen", "086_p_radio": "g_listen"}},
  "a2b1-087": {"canDo": "Ma loen näidisjuttu ja leian selle osad, kavandan oma loo ning kirjutan 90–110-sõnalise jutu etteantud pealkirjaga, kasutades minevikuvorme ja ajasõnu.", "goals": {"g_vocab": "Õpilane kasutab jutu sõnu: jutt, pealkiri, sündmus, juhtuma, äkki, lõpuks, tunne, mälestus, kirjeldama, plaan, komme, unustama; kirjutab kaheksa minutit järjest ja paneb ajasõnaga laused õigesse järjekorda.", "g_read": "Õpilane loeb Igori eksamijuttu tema esimesest jõululaupäevast Eestis, teksti Eesti jõulukommetest ja Hanna nõuandeid, leiab Sofia jutu iga lause ülesande ja saab kuuldust aru kuulaja loost raadios.", "g_notice": "Õpilane eristab lihtminevikku ja enneminevikku (läksin – olin unustanud), ühendab laused sidesõnadega (kuigi, sest, pärast seda kui, nii et), paneb tegusõna ajasõna järel teisele kohale ja parandab jutu vead.", "g_use": "Õpilane küsitleb kolme inimest meeldejäänud pühade kohta, vastab eksamineerija küsimustele pühade ja tähistamise kohta (Harno B1 rääkimine 1), valib koos Olenaga loo idee, jutustab oma loo salvestusel, kirjutab plaani ja 100-sõnalise jutu „Püha, mida ma ei unusta”."}},
  "a2b1-088": {"canDo": "Ma loen pere sõnumeid ja teksti võidupühast ja jaanipäevast, avaldan arvamust, lepin perega kokku, kus ja kuidas suurt pidu tähistada, ning tutvustan oma kodumaa püha.", "goals": {"g_vocab": "Õpilane kasutab peo ja arutelu sõnu: tähistama, pidu, ettepanek, arvamus, nõustuma, eelistama, kompromiss, otsustama, külaline, kutse, köögijuhataja, lõke; seob arutelu väljendid nende ülesandega ja täidab Viktori kirja.", "g_read": "Õpilane loeb pere grupivestlust, populaarteaduslikku teksti võidupühast ja jaanipäevast ning Viktori kolme kava ning saab kuuldust aru kümnest lühikesest sõnumist ja teatest.", "g_notice": "Õpilane avaldab arvamust ja teeb ettepaneku tingiva kõneviisiga (mis oleks, kui teeksime…, ma eelistaksin…, me võiksime…), nõustub osaliselt, pakub kompromissi (kui…, siis…) ja kinnitab otsuse (lepime kokku, et…).", "g_use": "Õpilane kirjutab sõnumi pere grupivestlusse, jutustab peost 4-3-2 meetodil, vastab „Mida sa teeksid?” küsimustele, täidab Viktori küsimustiku, vahetab infot peo ajakava jaoks, lepib kokku jaanipäeva kava (Harno B1 rääkimine 1, kokkulepe), peab ettekande oma kodumaa pühast ja kirjutab kutse."}},
  "a2b1-089": {"canDo": "Ma sooritan kolmanda täispika proovieksami Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin ning saan teada, kas olen eksamiks valmis — eesmärk on vähemalt 80 % igas osas.", "goals": {"g_read": "Õpilane lahendab Harno B1 lugemise (33 punkti, 50 min) ja kuulamise (30 punkti) neli ülesannet ajapiiranguga; eksamiks valmis on ta, kui saab lugemises vähemalt 27 ja kuulamises vähemalt 24 punkti.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Telefonikõne” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab õigesti mooduli 18 vorme: viisakas tingiv kõneviis (kas te saaksite…, ma eelistaksin…), umbisikuline minevik (jäeti ära), lihtminevik ja enneminevik jutus, ajasõna järel tegusõna teisel kohal, kokkuleppe väljendid.", "g_use": "Õpilane kirjutab teate ja isikliku kirja ning sooritab rääkimise osa (sissejuhatus, teemaküsimused, kokkulepe, telefonikõne); eksamiks valmis on ta, kui saab kirjutamises ja rääkimises vähemalt 16 punkti 20-st."}, "tags": {"089_p_l1": "g_listen", "089_p_l2": "g_listen", "089_p_l3k": "g_listen", "089_p_l4": "g_listen"}},
  "a2b1-090": {"canDo": "Ma sooritan kursuse lõpphindamise Harno B1 vormis ajapiiranguga: loen, kuulan, kirjutan ja räägin; kursuse tunnistuse saan, kui igas osas on vähemalt 80 %, ning sean endale järgmise eesmärgi.", "goals": {"g_read": "Õpilane lahendab lõpphindamise lugemise (33 punkti) ja kuulamise (30 punkti) osa ajapiiranguga ning saab kursuse tunnistuseks vähemalt 27 ja 24 punkti.", "g_listen": "Õpilane saab aru kuulamistekstidest „Lühikesed tekstid”, „Raadiolugu”, „Vestlus kontoris” ja „Intervjuu” (lüngad ja küsimused kuuldu kohta).", "g_notice": "Õpilane kasutab kursuse B1 grammatikat: umbisikuline tegumood, tingiv kõneviis, enneminevik, kuuldu edasiandmine (et-, kas-lause), rektsioon ja sõnajärg.", "g_use": "Õpilane täidab küsimustiku ja kirjutab jutu, sooritab rääkimise osa, saab kirjutamises ja rääkimises vähemalt 16 punkti 20-st ning koostab oma järgmise eesmärgi ja kordamis- või edasiõppimise kava."}, "tags": {"090_p_l1": "g_listen", "090_p_l2": "g_listen", "090_p_l3": "g_listen", "090_p_l4": "g_listen"}},
  // the e-exam format (b1/eeksam.js mock 1, b1/eeksamHarjutus.js practice): the listening lessons report g_listen
  "a2b1-ee1-l": {"canDo": "Ma saan aru arvamustest, monoloogist, lühikestest teadetest ja intervjuust ning kirjutan kuuldu põhjal lünka sõna või arvu.", "goals": {"g_listen": "Õpilane saab aru e-eksami kuulamistekstide põhimõttest ja detailidest (5 ülesannet, 35 küsimust) ning saab vähemalt 60 % õigeid vastuseid.", "g_use": "Õpilane kirjutab kuulamise ajal märkmeid ja hindab pärast, mis aitas."}, "tags": {"ee1_l_11": "g_listen", "ee1_l_12": "g_listen", "ee1_l_13": "g_listen", "ee1_l_14": "g_listen", "ee1_l_15": "g_listen"}},
  "a2b1-ee-p-l": {"canDo": "Ma tunnen e-eksami kolme kuulamisülesannet: sobitan kõneleja ja väite, otsustan, kas väide on õige või vale, ja kirjutan kuuldud sõna või arvu lünka.", "goals": {"g_listen": "Õpilane saab aru, mida eri inimesed liikumisest räägivad, leiab intervjuust õiged ja valed väited ning kirjutab teatest arvud ja sõnad.", "g_use": "Õpilane räägib oma liikumisharjumustest ja põhjendab, mida tahaks muuta."}, "tags": {"eep_l_1": "g_listen", "eep_l_2": "g_listen", "eep_l_3": "g_listen"}},
};
